const calculatorHtml = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>报价计算器</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\n\n:root {\n  --primary: #2563eb;\n  --primary-light: #dbeafe;\n  --primary-dark: #1d4ed8;\n  --success: #16a34a;\n  --success-light: #dcfce7;\n  --warning: #ea580c;\n  --warning-light: #fed7aa;\n  --gray-50: #f9fafb;\n  --gray-100: #f3f4f6;\n  --gray-200: #e5e7eb;\n  --gray-300: #d1d5db;\n  --gray-400: #9ca3af;\n  --gray-500: #6b7280;\n  --gray-600: #4b5563;\n  --gray-700: #374151;\n  --gray-800: #1f2937;\n  --gray-900: #111827;\n  --radius: 8px;\n  --shadow: 0 1px 2px rgba(0,0,0,0.08);\n}\n\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  background: var(--gray-100);\n  color: var(--gray-800);\n  line-height: 1.5;\n  min-height: 100vh;\n}\n\n/* 去掉数字输入框上下调节按钮 */\ninput[type=\"number\"]::-webkit-inner-spin-button,\ninput[type=\"number\"]::-webkit-outer-spin-button {\n  -webkit-appearance: none;\n  margin: 0;\n}\ninput[type=\"number\"] {\n  -moz-appearance: textfield;\n}\n\n/* ===== Parse Bar ===== */\n.parse-section {\n  max-width: 1500px;\n  margin: 14px auto 0;\n  padding: 0 14px;\n}\n.parse-row {\n  display: flex;\n  gap: 8px;\n}\n.parse-input {\n  flex: 1;\n  padding: 9px 14px;\n  border: 2px solid var(--primary);\n  border-radius: 8px;\n  font-size: 13px;\n  font-family: inherit;\n  background: white;\n  color: var(--gray-800);\n}\n.parse-input:focus {\n  outline: none;\n  box-shadow: 0 0 0 3px rgba(37,99,235,0.15);\n}\n.parse-btn {\n  padding: 9px 18px;\n  background: var(--primary);\n  color: white;\n  border: none;\n  border-radius: 8px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  font-family: inherit;\n  white-space: nowrap;\n  transition: background 0.2s;\n}\n.parse-btn:hover { background: var(--primary-dark); }\n.img-upload-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  padding: 9px 12px; background: var(--gray-100); color: var(--gray-700);\n  border: 1px solid var(--gray-300); border-radius: 8px;\n  font-size: 16px; cursor: pointer; transition: background 0.2s;\n}\n.img-upload-btn:hover { background: var(--gray-200); }\n.parse-result {\n  margin-top: 5px;\n  font-size: 12px;\n  color: var(--gray-600);\n  min-height: 16px;\n  line-height: 1.4;\n}\n.parse-result .ok { color: var(--success); font-weight: 600; }\n.parse-result .fail { color: #dc2626; }\n.ph-examples-hidden { display: none; }\n\n/* ===== Cheatsheet ===== */\n/* ===== Header ===== */\n.header {\n  background: #1e3a5f;\n  color: white;\n  padding: 8px 16px;\n  box-shadow: 0 1px 4px rgba(0,0,0,0.12);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px 12px;\n  flex-wrap: wrap;\n}\n.header h1 { font-size: 17px; font-weight: 700; line-height: 1.25; white-space: nowrap; }\n.header-actions { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }\n.header-actions button { flex: 0 0 auto; white-space: nowrap; line-height: 1.25; }\n.header-actions .reset-btn { width: auto; padding: 6px 12px; border-color: rgba(255,255,255,0.4); color: white; background: rgba(255,255,255,0.1); }\n.header-actions .print-btn { padding: 6px 12px; }\n.header p { font-size: 11px; opacity: 0.8; margin-top: 1px; }\n\n/* ===== Layout ===== */\n.main-wrap {\n  display: grid;\n  grid-template-columns: 1fr 340px;\n  gap: 14px;\n  max-width: 1500px;\n  margin: 14px auto;\n  padding: 0 14px;\n  align-items: start;\n}\n.left-col { display: flex; flex-direction: column; gap: 14px; }\n.right-col { position: sticky; top: 66px; }\n\n/* ===== Module Card ===== */\n.module {\n  background: white;\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n  overflow: hidden;\n}\n.module-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 16px;\n  font-size: 14px;\n  font-weight: 700;\n  color: white;\n}\n.module-header .m-num {\n  width: 22px; height: 22px;\n  border-radius: 50%;\n  background: rgba(255,255,255,0.25);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; font-weight: 700;\n  flex-shrink: 0;\n}\n.mh-1 { background: #0ea5e9; }\n.mh-2 { background: #8b5cf6; }\n.mh-3 { background: #f59e0b; }\n.mh-4 { background: #10b981; }\n\n.module-body { padding: 14px 16px; }\n\n/* ===== Form ===== */\n.form-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));\n  gap: 10px;\n  margin-bottom: 10px;\n}\n.form-grid.tight { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); }\n.form-grid.tight.tax-ship-row { grid-template-columns: 1fr 1fr 1fr 4fr; }\n.fg-span2 { grid-column: span 2; }\n.fg-fill { grid-column: 1 / -1; }\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n.form-group label {\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--gray-600);\n}\n.form-group label .unit {\n  font-weight: 400;\n  color: var(--gray-400);\n  font-size: 10px;\n}\n.form-control {\n  padding: 6px 8px;\n  border: 1px solid var(--gray-300);\n  border-radius: 6px;\n  font-size: 13px;\n  transition: all 0.2s;\n  background: white;\n  color: var(--gray-800);\n  font-family: inherit;\n  width: 100%;\n}\n.form-control:focus {\n  outline: none;\n  border-color: var(--primary);\n  box-shadow: 0 0 0 2px rgba(37,99,235,0.1);\n}\n.form-control.auto {\n  background: #fffbeb;\n  border-color: var(--warning-light);\n  color: var(--warning);\n  font-weight: 600;\n}\nselect.form-control {\n  cursor: pointer;\n  appearance: none;\n  background-image: url(\"data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%236b7280' stroke-width='2'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e\");\n  background-repeat: no-repeat;\n  background-position: right 6px center;\n  background-size: 12px;\n  padding-right: 24px;\n}\n\n/* ===== Type Cards ===== */\n.type-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n  margin-bottom: 10px;\n}\n.type-chip {\n  padding: 5px 11px;\n  border: 1px solid var(--gray-300);\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 12px;\n  font-weight: 500;\n  transition: all 0.15s;\n  background: white;\n  color: var(--gray-600);\n}\n.type-chip:hover { border-color: var(--primary); }\n.type-chip.active { background: var(--primary); color: white; border-color: var(--primary); }\n.type-chip.sub { font-size: 12px; padding: 5px 11px; background: #fff; }\n.type-chip.sub.active { background: var(--primary); color: #fff; border-style: solid; border-color: var(--primary); }\n\n/* ===== Sub-label ===== */\n.sub-label {\n  font-size: 11px;\n  font-weight: 700;\n  color: var(--gray-500);\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n  margin-bottom: 6px;\n  margin-top: 2px;\n  padding-bottom: 3px;\n  border-bottom: 1px solid var(--gray-100);\n}\n\n/* ===== Inline Results ===== */\n.inline-results {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 8px;\n  padding-top: 8px;\n  border-top: 1px dashed var(--gray-200);\n}\n.ir-item {\n  background: var(--gray-50);\n  border-radius: 5px;\n  padding: 6px 10px;\n  border-left: 2px solid var(--primary);\n  min-width: 80px;\n}\n.ir-item.warn { border-left-color: var(--warning); background: #fffbeb; }\n.ir-item.ok { border-left-color: var(--success); background: var(--success-light); }\n.ir-item.info { border-left-color: var(--primary); background: var(--primary-light); }\n.ir-item .ir-label { font-size: 10px; color: var(--gray-500); margin-bottom: 1px; }\n.ir-item .ir-value { font-size: 14px; font-weight: 700; color: var(--gray-800); }\n.ir-item .ir-unit { font-size: 10px; color: var(--gray-400); }\n.ir-item.warn .ir-value { color: var(--warning); }\n.ir-item.ok .ir-value { color: var(--success); }\n.ir-item.info .ir-value { color: var(--primary); }\n\n/* ===== 计算过程（产品体量上方展示） ===== */\n.calc-process {\n  background: var(--gray-50);\n  border: 1px solid var(--gray-200);\n  border-radius: 6px;\n  padding: 8px 10px;\n  margin-top: 6px;\n  margin-bottom: 12px;\n  font-size: 11px;\n  line-height: 1.85;\n  color: var(--gray-800);\n  overflow-x: auto;\n}\n.calc-process .cp-line { white-space: nowrap; }\n.calc-process .cp-k { color: var(--gray-500); font-weight: 600; }\n.calc-process .cp-expr { color: var(--gray-800); }\n.calc-process .cp-calc { color: #475569; }\n.calc-process .cp-v { color: var(--primary); font-weight: 700; }\n.calc-process .cp-sep { color: var(--gray-400); margin: 0 4px; }\n.calc-process .cp-head { font-weight: 700; color: var(--warning); margin: 5px 0 1px; }\n\n/* ===== Checkbox Grid ===== */\n.cb-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\n  gap: 6px;\n  margin-bottom: 8px;\n}\n.cb-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 8px;\n  border: 1px solid var(--gray-200);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.15s;\n  background: white;\n}\n.cb-item:hover { border-color: var(--primary); }\n.cb-item.checked { border-color: var(--success); background: var(--success-light); }\n.cb-item-wide {\n  grid-column: 1 / -1;  /* 占满整行 */\n}\n.cb-trio {\n  display: flex;\n  gap: 6px;\n  margin-bottom: 6px;\n}\n.cb-trio > .cb-item {\n  flex: 1;\n}\n.cb-item-stack {\n  flex-direction: column;\n  align-items: stretch;\n  gap: 4px;\n}\n.cb-item-stack .cb-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.cb-item-stack .cb-row2 {\n  display: flex;\n  align-items: center;\n  padding-left: 20px;  /* 与 checkbox 对齐 */\n}\n.cb-item input[type=\"checkbox\"] {\n  width: 14px; height: 14px;\n  accent-color: var(--success);\n  cursor: pointer;\n  flex-shrink: 0;\n}\n.cb-item .cb-text { font-size: 11px; font-weight: 500; flex: 1; line-height: 1.3; }\n.cb-item input[type=\"number\"] {\n  width: 46px;\n  padding: 2px 5px;\n  border: 1px solid var(--gray-300);\n  border-radius: 4px;\n  font-size: 11px;\n  text-align: right;\n}\n.cb-item input[type=\"number\"].cb-input-wide {\n  width: 92px;\n}\n.cb-item .cb-auto {\n  font-size: 11px;\n  font-weight: 700;\n  color: var(--gray-400);\n  background: var(--gray-100);\n  padding: 2px 5px;\n  border-radius: 4px;\n}\n.cb-item.checked .cb-auto { color: var(--success); background: white; }\n.cb-item .auto-tag {\n  font-size: 10px;\n  font-weight: 600;\n  padding: 1px 5px;\n  border-radius: 4px;\n  white-space: nowrap;\n}\n.cb-item .auto-tag.auto { color: #2563eb; background: #eff6ff; }\n.cb-item .auto-tag.manual { color: #b45309; background: #fef3c7; }\n.req { color: #dc2626; font-weight: 700; margin-left: 2px; }\n\n/* ===== Add Custom Checkbox Button ===== */\n.add-cb-btn {\n  padding: 5px 12px;\n  border: 1px dashed var(--primary);\n  border-radius: 6px;\n  background: var(--primary-light);\n  color: var(--primary);\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  font-family: inherit;\n  transition: all 0.15s;\n}\n.add-cb-btn:hover { background: var(--primary); color: white; border-style: solid; }\n.cb-item.custom { border-style: dashed; border-color: var(--primary); }\n.cb-item.custom.checked { border-style: solid; }\n.cb-item.custom .cb-text-input {\n  font-size: 11px;\n  font-weight: 500;\n  border: none;\n  background: transparent;\n  color: var(--gray-800);\n  width: 100%;\n  padding: 0;\n  font-family: inherit;\n  outline: none;\n}\n.cb-item.custom .cb-text-input:focus { border-bottom: 1px dotted var(--primary); }\n.cb-item.custom .cb-del-btn {\n  font-size: 13px;\n  color: #dc2626;\n  cursor: pointer;\n  margin-left: 4px;\n  font-weight: 700;\n  opacity: 0.4;\n  transition: opacity 0.15s;\n}\n.cb-item.custom .cb-del-btn:hover { opacity: 1; }\n\n/* ===== Right Panel: Summary ===== */\n.summary-panel {\n  background: white;\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n  overflow: hidden;\n}\n.summary-header {\n  background: #1e3a5f;\n  color: white;\n  padding: 12px 16px;\n}\n.summary-header h2 { font-size: 14px; font-weight: 700; }\n.summary-header p { font-size: 10px; opacity: 0.8; }\n\n.summary-body { padding: 14px 16px; }\n\n.flow-chain {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  margin-bottom: 12px;\n}\n.flow-node {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  border-radius: 6px;\n  background: var(--gray-50);\n  position: relative;\n}\n.flow-node.active { background: var(--primary-light); }\n.flow-node .fn-dot {\n  width: 6px; height: 6px;\n  border-radius: 50%;\n  background: var(--gray-300);\n  flex-shrink: 0;\n}\n.flow-node.active .fn-dot { background: var(--primary); }\n.flow-node .fn-label { font-size: 11px; color: var(--gray-500); flex: 1; }\n.flow-node .fn-value { font-size: 13px; font-weight: 700; color: var(--gray-800); }\n.flow-arrow {\n  text-align: center;\n  color: var(--gray-300);\n  font-size: 12px;\n  line-height: 1;\n  padding: 1px 0;\n  margin-left: 14px;\n}\n\n.final-box {\n  background: linear-gradient(135deg, #16a34a 0%, #059669 100%);\n  color: white;\n  border-radius: var(--radius);\n  padding: 14px;\n  text-align: center;\n  margin-bottom: 10px;\n}\n.final-box .fb-label { font-size: 12px; opacity: 0.9; }\n.final-box .fb-value { font-size: 30px; font-weight: 800; margin: 2px 0; }\n.final-box .fb-unit { font-size: 12px; opacity: 0.8; }\n\n.quote-stack {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 10px;\n}\n.quote-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 9px 12px;\n  background: var(--gray-50);\n  border: 1px solid var(--gray-200);\n  border-radius: 8px;\n}\n.quote-row .qr-label { font-size: 12px; color: var(--gray-600); }\n.quote-row .qr-value { font-size: 16px; font-weight: 700; color: var(--gray-800); }\n.quote-row.hl {\n  background: #fff7ed;\n  border-color: var(--warning);\n}\n.quote-row.hl .qr-label { color: #c2410c; font-weight: 600; }\n.quote-row.hl .qr-value { color: var(--warning); font-size: 18px; }\n\n.detail-table {\n  width: 100%;\n  font-size: 11px;\n  border-collapse: collapse;\n}\n.detail-table th {\n  text-align: left;\n  padding: 5px 6px;\n  color: var(--gray-500);\n  font-weight: 600;\n  border-bottom: 1px solid var(--gray-200);\n}\n.detail-table td {\n  padding: 5px 6px;\n  border-bottom: 1px solid var(--gray-100);\n  color: var(--gray-700);\n}\n.detail-table tr:last-child td { border-bottom: none; }\n\n/* ===== Badge ===== */\n.badge {\n  display: inline-block;\n  padding: 0 4px;\n  border-radius: 3px;\n  font-size: 9px;\n  font-weight: 600;\n}\n.badge-auto { background: var(--warning-light); color: var(--warning); }\n\n/* ===== Reset button ===== */\n.reset-btn {\n  width: 100%;\n  padding: 8px;\n  border: 1px solid var(--gray-300);\n  border-radius: 6px;\n  background: white;\n  color: var(--gray-600);\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.2s;\n  font-family: inherit;\n}\n.reset-btn:hover { border-color: var(--gray-400); background: var(--gray-50); }\n\n/* ===== Responsive ===== */\n@media (max-width: 1100px) {\n  .main-wrap { grid-template-columns: 1fr; }\n  .right-col { position: static; }\n}\n@media (max-width: 600px) {\n  .form-grid { grid-template-columns: 1fr 1fr; }\n  .header h1 { font-size: 15px; }\n  .main-wrap { padding: 0 10px; }\n}\n\n/* ===== 打印报价单按钮 ===== */\n.print-btn {\n  width:auto; padding:8px 16px; border:1px solid rgba(255,255,255,0.4);\n  color:white; background:#16a34a; border-radius:8px; cursor:pointer; font-size:13px; font-weight:600;\n}\n.print-btn:hover { background:#15803d; }\n\n/* ===== 打印弹窗 ===== */\n.print-overlay {\n  position: fixed; inset:0; background:rgba(0,0,0,0.55); z-index:9999;\n  display:none; align-items:flex-start; justify-content:center; padding:24px; overflow:auto;\n}\n.print-overlay.show { display:flex; }\n.auth-overlay { position:fixed; inset:0; z-index:9999; display:flex; align-items:center; justify-content:center; background:rgba(15,23,42,.92); backdrop-filter:blur(4px); }\n.auth-box { background:#fff; border-radius:14px; padding:28px 32px; width:min(92vw,380px); box-shadow:0 20px 60px rgba(0,0,0,.3); text-align:center; }\n.auth-box h2 { margin:0 0 4px; font-size:20px; color:#0f172a; }\n.auth-hint { font-size:12px; color:#64748b; margin:0 0 14px; }\n.auth-input { width:100%; padding:10px 12px; border:1px solid #cbd5e1; border-radius:8px; font-size:14px; margin-bottom:10px; box-sizing:border-box; }\n.auth-btn { display:block; width:100%; padding:10px; border:none; border-radius:8px; background:#16a34a; color:#fff; font-size:14px; font-weight:600; cursor:pointer; }\n.auth-btn.ghost { background:#e2e8f0; color:#475569; margin-top:8px; }\n.auth-err { color:#dc2626; font-size:12px; min-height:16px; margin-top:6px; }\n.print-sheet {\n  background:#fff; width:1123px; max-width:100%; min-height:794px; color:#111;\n  padding:28px 32px; box-shadow:0 10px 40px rgba(0,0,0,0.3); font-size:13px; line-height:1.6;\n}\n.print-sheet h1 { font-size:22px; text-align:center; margin:0 0 4px; letter-spacing:2px; }\n.print-sheet .ps-sub { text-align:center; color:#666; font-size:12px; margin-bottom:16px; }\n.print-sheet .ps-meta { display:flex; justify-content:space-between; font-size:12px; color:#444; border-bottom:1px solid #ddd; padding-bottom:8px; margin-bottom:14px; }\n.ps-section { margin-bottom:18px; }\n.ps-section h2 { font-size:15px; border-left:4px solid #2563eb; padding-left:8px; margin:0 0 10px; }\n.ps-section.verify h2 { border-left-color:#f59e0b; }\n.ps-grid { display:grid; grid-template-columns:1fr 1fr 1fr; gap:6px 18px; }\n.ps-grid.two { grid-template-columns:1fr 1fr; }\n.ps-item { display:flex; justify-content:space-between; border-bottom:1px dotted #eee; padding:3px 0; }\n.ps-item .k { color:#555; }\n.ps-item .v { font-weight:600; }\n.ps-final { text-align:center; background:#f0f9ff; border:1px solid #bae6fd; border-radius:10px; padding:14px; margin:8px 0 4px; }\n.ps-final .pf-price { font-size:26px; font-weight:700; color:#0369a1; }\n.ps-final .pf-total { font-size:16px; font-weight:600; color:#0f172a; margin-top:4px; }\n.ps-table { width:100%; border-collapse:collapse; font-size:12px; }\n.ps-table th, .ps-table td { border:1px solid #ddd; padding:5px 8px; text-align:left; }\n.ps-table th { background:#f8fafc; }\n.ps-table td.num, .ps-table th.num { text-align:right; }\n.ps-divider { border-top:2px dashed #cbd5e1; margin:16px 0; }\n\n/* ===== 计算联 三列布局 ===== */\n.calc-trio { display:flex; gap:14px; align-items:stretch; margin-top:6px; }\n.calc-col { flex:1; min-width:0; }\n.calc-head { font-size:13px; font-weight:700; color:#0369a1; margin-bottom:6px; padding-bottom:5px; border-bottom:2px solid #0369a1; }\n.calc-list { display:flex; flex-direction:column; gap:3px; }\n.calc-row { display:flex; justify-content:space-between; font-size:12px; border-bottom:1px dotted #eee; padding:3px 0; }\n.calc-row span { color:#555; }\n.calc-row b { font-weight:600; color:#0f172a; }\n.calc-addr-row { display:flex; justify-content:space-between; gap:14px; }\n.addr-col { display:flex; align-items:center; gap:6px; flex:1; }\n.addr-label { margin-left:8px; }\n.calc-row-sub { font-size:11px; padding-left:12px; color:#64748b; border-bottom:1px dotted #f1f5f9; }\n.calc-row-sub span { color:#94a3b8; font-size:11px; }\n.calc-row-sub b { font-weight:600; color:#334155; font-size:11px; }\n.calc-step { font-size:12px; padding:4px 0; border-bottom:1px dotted #eee; color:#334155; line-height:1.5; }\n.calc-step b { color:#0369a1; font-weight:700; }\n.calc-step span { color:#94a3b8; font-size:11px; }\n.calc-subtitle { font-size:12px; font-weight:700; color:#475569; margin:8px 0 4px; padding-bottom:3px; border-bottom:1px solid #e2e8f0; }\n.calc-proc-table { width:100%; font-size:11px; border-collapse:collapse; }\n.calc-proc-table td { padding:3px 0; border-bottom:1px dotted #eee; }\n.calc-proc-table td.num { text-align:right; font-weight:600; color:#0f172a; }\n.calc-row-big { font-size:14px; padding:6px 0; border-bottom:1px solid #e2e8f0; }\n.calc-row-big b { font-size:16px; color:#be123c !important; }\n.print-sheet .calc-col:last-child .calc-head { color:#be123c; border-bottom-color:#be123c; }\n.line-hide-btn { margin-left:8px; font-size:10px; cursor:pointer; color:#0369a1; background:#e0f2fe; border:1px solid #bae6fd; border-radius:4px; padding:1px 6px; }\n.line-hide-btn:hover { background:#bae6fd; }\n@media print { .line-hide-btn { display:none !important; } }\n@media screen {\n  .calc-row.hidden-line, .print-line.hidden-line {\n    display:flex !important;\n    min-height:28px;\n    align-items:center;\n    justify-content:flex-end;\n    background:#f8fafc;\n    border:1px dashed #cbd5e1;\n    padding-right:0;\n  }\n  .calc-row.hidden-line > *:not(.line-hide-btn),\n  .print-line.hidden-line > *:not(.line-hide-btn) { display:none !important; }\n  .calc-row.hidden-line .line-hide-btn,\n  .print-line.hidden-line .line-hide-btn { margin-right:0; }\n}\n@media print {\n  .calc-row.hidden-line, .print-line.hidden-line { display:none !important; }\n}\n.ps-hint { font-size:11px; color:#94a3b8; text-align:center; margin-top:10px; }\n.ps-actions { text-align:center; margin-top:18px; }\n.ps-actions button { margin:0 6px; padding:9px 22px; border-radius:8px; border:1px solid #2563eb; background:#2563eb; color:#fff; cursor:pointer; font-size:13px; font-weight:600; }\n.ps-actions button.ghost { background:#fff; color:#2563eb; }\n\n/* 打印内容选择条 */\n.ps-printopts { display:flex; align-items:center; gap:6px; margin:14px 0 6px; padding:8px 10px; background:#f1f5f9; border-radius:8px; }\n.ps-opt-label { font-size:13px; color:#475569; font-weight:600; margin-right:4px; }\n.ps-opt { padding:6px 16px; border-radius:7px; border:1px solid #cbd5e1; background:#fff; color:#334155; cursor:pointer; font-size:13px; font-weight:600; transition:all .12s; }\n.ps-opt:hover { border-color:#2563eb; color:#2563eb; }\n.ps-opt.active { background:#2563eb; border-color:#2563eb; color:#fff; }\n\n/* 打印时只保留报价单本身 */\n@media print {\n  /* 默认 A4 横版 */\n  @page { size: A4 landscape; margin: 8mm; }\n  body * { visibility:hidden; }\n  .print-overlay, .print-overlay * { visibility:visible; }\n  /* 关键修复：把非打印区（主计算界面）彻底移出文档流，避免占据高度导致多出空白页 */\n  body > *:not(.print-overlay) { display:none !important; }\n  .print-overlay { position:absolute; inset:0; background:#fff; padding:0; display:block !important; height:auto; min-height:0; }\n  .print-sheet { box-shadow:none; width:100%; min-height:auto; padding:0; height:auto; page-break-after:avoid; }\n  .ps-actions, .ps-hint, .ps-printopts { display:none !important; }\n}\n</style>\n</head>\n<body>\n\n<!-- 管理员登录 -->\n<div id=\"authOverlay\" class=\"auth-overlay\" style=\"display:none;\">\n  <div class=\"auth-box\">\n    <h2>管理员登录</h2>\n    <input type=\"password\" id=\"authPwd\" class=\"auth-input\" placeholder=\"请输入密码\" onkeydown=\"if(event.key==='Enter')checkAuth()\">\n    <div id=\"authErr\" class=\"auth-err\"></div>\n    <button class=\"auth-btn\" onclick=\"checkAuth()\">管理员登录</button>\n    <button class=\"auth-btn ghost\" onclick=\"document.getElementById('authOverlay').style.display='none'\">返回计算器</button>\n  </div>\n</div>\n\n<!-- 存为模板确认弹窗 -->\n<div id=\"tplConfirm\" class=\"auth-overlay\" style=\"display:none;\">\n  <div class=\"auth-box\">\n    <h2>存为模板确认</h2>\n    <p>确定将当前配置存为模板吗？</p>\n    <button class=\"auth-btn\" onclick=\"doSaveTemplate()\">是</button>\n    <button class=\"auth-btn ghost\" onclick=\"hideTplConfirm()\">否</button>\n  </div>\n</div>\n\n<!-- 重置确认弹窗（必须放在 auth-overlay 外面） -->\n<div id=\"resetConfirm\" class=\"auth-overlay\" style=\"display:none;\">\n  <div class=\"auth-box\">\n    <h2>确认重置</h2>\n    <p id=\"resetConfirmText\">确定要重置吗？</p>\n    <button class=\"auth-btn\" onclick=\"doReset()\">是，重置</button>\n    <button class=\"auth-btn ghost\" onclick=\"hideResetConfirm()\">取消</button>\n  </div>\n</div>\n\n<div class=\"header\">\n  <div>\n    <h1>报价计算器</h1>\n  </div>\n  <div class=\"header-actions\">\n    <button class=\"reset-btn\" onclick=\"document.getElementById('authOverlay').style.display='flex'\">管理员登录</button>\n    <button class=\"print-btn\" onclick=\"openPrintSheet()\">🖨 打印报价单</button>\n    <button class=\"reset-btn\" onclick=\"confirmReset()\">↻ 重置</button>\n    <button class=\"reset-btn admin-only\" onclick=\"saveAsTemplate()\">★ 存为模板</button>\n  </div>\n</div>\n\n<div class=\"parse-section\">\n  <div class=\"parse-row\">\n    <input type=\"text\" id=\"parseInput\" class=\"parse-input\" placeholder=\"如：板 3 600 1000 300×200×100 普通 含税7% 钉0.5\" onkeydown=\"if(event.key==='Enter')parseAndFill()\">\n    <label class=\"img-upload-btn\" title=\"上传图片识别\">\n      📷<input type=\"file\" id=\"imgParseInput\" accept=\"image/*\" style=\"display:none\" onchange=\"ocrAndFill(this)\">\n    </label>\n    <button class=\"parse-btn\" onclick=\"parseAndFill()\">识别填写</button>\n  </div>\n  <div id=\"parseResult\" class=\"parse-result\"></div>\n  </div>\n\n<div class=\"main-wrap\">\n</div>\n\n<div class=\"main-wrap\">\n<div class=\"left-col\">\n\n<!-- ==================== Board 1: 产品参数 ==================== -->\n<div class=\"module\">\n  <div class=\"module-header mh-1\">\n    <span class=\"m-num\">1</span>\n    产品参数\n  </div>\n  <div class=\"module-body\">\n    <div class=\"sub-label\">产品样式</div>\n    <div class=\"type-row\" id=\"s1_style_row\">\n      <div class=\"type-chip\" data-style=\"板材\" onclick=\"selectStyle(this)\">板材</div>\n      <div class=\"type-chip\" data-style=\"箱子\" onclick=\"selectStyle(this)\">箱子</div>\n      <div class=\"type-chip\" data-style=\"盒子\" onclick=\"selectStyle(this)\">盒子</div>\n      <div class=\"type-chip\" data-style=\"圆盘\" onclick=\"selectStyle(this)\">圆盘</div>\n    </div>\n\n    <div class=\"type-row\" id=\"s1_box_sub_row\" style=\"display:none; margin-top:6px;\">\n      <div class=\"type-chip sub\" data-style=\"纸箱式\" onclick=\"selectStyle(this)\">纸箱式</div>\n      <div class=\"type-chip sub\" data-style=\"插底式\" onclick=\"selectStyle(this)\">插底式</div>\n      <div class=\"type-chip sub\" data-style=\"焊底式\" onclick=\"selectStyle(this)\">焊底式</div>\n      <div class=\"type-chip sub\" data-style=\"骨架箱\" onclick=\"selectStyle(this)\">骨架箱</div>\n      <div class=\"type-chip sub\" data-style=\"全包式\" onclick=\"selectStyle(this)\">全包式</div>\n      <div class=\"type-chip sub\" data-style=\"四拼式\" onclick=\"selectStyle(this)\">四拼式</div>\n    </div>\n\n    <div class=\"type-row\" id=\"s1_case_sub_row\" style=\"display:none; margin-top:6px;\">\n      <div class=\"type-chip sub\" data-style=\"投票箱\" onclick=\"selectStyle(this)\">投票箱</div>\n    </div>\n\n    <div class=\"type-row\" id=\"s1_dimtype_row\" style=\"display:none;\">\n      <div class=\"type-chip\" data-dim=\"外尺\" onclick=\"selectDimType(this)\">外尺</div>\n      <div class=\"type-chip\" data-dim=\"内尺\" onclick=\"selectDimType(this)\">内尺</div>\n    </div>\n\n    <div class=\"sub-label\">基础参数</div>\n    <div class=\"form-grid\">\n      <div class=\"form-group\">\n        <label>厚度 <span class=\"unit\">mm</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_thickness\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n      <div class=\"form-group\">\n        <label>克重 <span class=\"unit\">g/㎡</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_weight\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n      <div class=\"form-group\">\n        <label>长 / 外直径 <span class=\"unit\">mm</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_length\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n      <div class=\"form-group\">\n        <label>宽 / 内直径 <span class=\"unit\">mm</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_width\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n      <div class=\"form-group\" id=\"s1_height_group\">\n        <label>高 <span class=\"unit\">mm</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_height\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n      <div class=\"form-group\" id=\"s1_usageRate_group\">\n        <label>使用率 <span class=\"unit\">%</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_usageRate\" value=\"100\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>数量 <span class=\"unit\">个</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_quantity\" value=\"\" oninput=\"calcAll()\" placeholder=\"填写\">\n      </div>\n    </div>\n\n    <div class=\"sub-label\">计算过程</div>\n    <div class=\"calc-process\" id=\"r1_process\"></div>\n\n    <div class=\"sub-label\">产品体量</div>\n    <div class=\"inline-results\">\n      <div class=\"ir-item\"><div class=\"ir-label\" id=\"r1_sheetL_label\">板材长</div><div class=\"ir-value\" id=\"r1_sheetL\">300</div><div class=\"ir-unit\">mm</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\" id=\"r1_sheetW_label\">板材宽</div><div class=\"ir-value\" id=\"r1_sheetW\">200</div><div class=\"ir-unit\">mm</div></div>\n      <div class=\"ir-item\" id=\"r1_b2\"><div class=\"ir-label\" id=\"r1_sheetL2_label\">板材长②</div><div class=\"ir-value\" id=\"r1_sheetL2\">—</div><div class=\"ir-unit\">mm</div></div>\n      <div class=\"ir-item\" id=\"r1_bw2\"><div class=\"ir-label\" id=\"r1_sheetW2_label\">板材宽②</div><div class=\"ir-value\" id=\"r1_sheetW2\">—</div><div class=\"ir-unit\">mm</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">单产品面积</div><div class=\"ir-value\" id=\"r1_area\">0.060</div><div class=\"ir-unit\">㎡</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">总立方数</div><div class=\"ir-value\" id=\"r1_volume\">0.18</div><div class=\"ir-unit\">m³</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">总吨数</div><div class=\"ir-value\" id=\"r1_tons\">0.04</div><div class=\"ir-unit\">T</div></div>\n    </div>\n\n  </div>\n</div>\n\n<!-- ==================== Board 2: 价格计算 ==================== -->\n<div class=\"module\">\n  <div class=\"module-header mh-2\">\n    <span class=\"m-num\">2</span>\n    价格计算\n  </div>\n  <div class=\"module-body\">\n\n    <!-- 报价参数（按调整要求从「产品和报价参数」板块移入，置于价格计算顶部） -->\n    <!-- 原\"是否含税\" sub-label 已删除（v94）：重复标签，与下方 label 同名；标题改由\"原料/板材价格计算\"承担 -->\n    <div class=\"sub-label\">税运情况</div>\n    <div class=\"form-grid tight tax-ship-row\">\n      <div class=\"form-group\">\n        <label>是否含税</label>\n        <select class=\"form-control\" id=\"s1_tax\" onchange=\"calcAll()\">\n          <option value=\"是\">是</option>\n          <option value=\"否\">否</option>\n        </select>\n      </div>\n      <div class=\"form-group\" id=\"s1_taxRate_group\">\n        <label>税点 <span class=\"unit\">%</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s1_taxRate\" value=\"7\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>是否含运</label>\n        <select class=\"form-control\" id=\"s1_shipFee\" onchange=\"calcAll()\">\n          <option value=\"是\" selected>是</option>\n          <option value=\"否\">否</option>\n        </select>\n      </div>\n      <div class=\"form-group\">\n        <label>客户收货地址</label>\n        <input type=\"text\" class=\"form-control\" id=\"s1_address\" placeholder=\"如：广东省深圳市南山区XX路XX号\" oninput=\"calcAll()\">\n      </div>\n    </div>\n\n    <!-- 原料/板材价格计算（v94 新增：在原料配方上方加此 sub-label 作为分区标题） -->\n    <div class=\"sub-label\">原料/板材价格计算</div>\n\n    <!-- 原料配方（原「板材类型」，置于原料价格计算之上） -->\n    <div class=\"sub-label\">原料配方</div>\n    <div class=\"type-row\" id=\"s2_type_row\">\n      <div class=\"type-chip active\" data-type=\"普通\" onclick=\"selectMaterialType(this)\">普通</div>\n      <div class=\"type-chip\" data-type=\"回料+母料\" onclick=\"selectMaterialType(this)\">回料+母料</div>\n      <div class=\"type-chip\" data-type=\"新料+透明母料\" onclick=\"selectMaterialType(this)\">新料+透明母料</div>\n      <div class=\"type-chip\" data-type=\"防静电\" onclick=\"selectMaterialType(this)\">防静电</div>\n      <div class=\"type-chip\" data-type=\"导电\" onclick=\"selectMaterialType(this)\">导电</div>\n      <div class=\"type-chip\" data-type=\"耐低温\" onclick=\"selectMaterialType(this)\">耐低温</div>\n      <div class=\"type-chip\" data-type=\"阻燃\" onclick=\"selectMaterialType(this)\">阻燃</div>\n    </div>\n\n    <!-- 原料配方输入区（绿色框） -->\n    <div class=\"form-grid tight\" id=\"s2_recipe_grid\">\n      <div class=\"form-group\" id=\"grp_newPrice\" style=\"display:none;\">\n        <label>新料 <span class=\"unit\">元/吨</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_newPrice\" value=\"9000\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\" id=\"grp_newRatio\" style=\"display:none;\">\n        <label>新料比例 <span class=\"unit\">%</span></label>\n        <input type=\"text\" class=\"form-control\" id=\"s2_newRatio\" value=\"100\" readonly style=\"background:#f3f4f6; cursor:not-allowed;\">\n      </div>\n      <div class=\"form-group\" id=\"grp_masterPrice\" style=\"display:none;\">\n        <label>母料 <span class=\"unit\">元/吨</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_masterPrice\" value=\"2000\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\" id=\"grp_masterRatio\" style=\"display:none;\">\n        <label>母料比例 <span class=\"unit\">%</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_masterRatio\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\" id=\"grp_specialPrice\" style=\"display:none;\">\n        <label>特殊料 <span class=\"unit\">元/吨</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_specialPrice\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\" id=\"grp_specialRatio\" style=\"display:none;\">\n        <label>特殊料比例 <span class=\"unit\">%</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_specialRatio\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n    </div>\n    <div class=\"form-grid tight\">\n      <div class=\"form-group\">\n        <label>固定成本 <span class=\"unit\">元/吨</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_fixedCost\" value=\"1700\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>原料利润 <span class=\"unit\">元/吨</span> <span style=\"color:#dc2626;\">*</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s2_profit\" value=\"0\" oninput=\"calcAll()\" placeholder=\"0\">\n      </div>\n    </div>\n\n    <!-- 2.1 计算过程（从原\"原料价格计算\"标题改名为\"计算过程\"，下移至配方输入框之后） -->\n    <div class=\"sub-label\">计算过程</div>\n    <div class=\"calc-process\" id=\"r2_process\"></div>\n\n    <div class=\"inline-results\">\n      <div class=\"ir-item\"><div class=\"ir-label\">原料成本</div><div class=\"ir-value\" id=\"r2_materialCost\">6205</div><div class=\"ir-unit\">元/吨</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">原料售价</div><div class=\"ir-value\" id=\"r2_materialPrice\">8256</div><div class=\"ir-unit\">元/吨</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">克重</div><div class=\"ir-value\" id=\"r2_weight\">600</div><div class=\"ir-unit\">g/㎡</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">平方价</div><div class=\"ir-value\" id=\"r2_sqPrice\">4.95</div><div class=\"ir-unit\">元/㎡</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">单产品面积</div><div class=\"ir-value\" id=\"r2_area\">0.060</div><div class=\"ir-unit\">㎡</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">板材售价（单）</div><div class=\"ir-value\" id=\"r2_sheetUnitPrice\">0.00</div><div class=\"ir-unit\">元</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">数量</div><div class=\"ir-value\" id=\"r2_sheetQty\">0</div><div class=\"ir-unit\">个</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">板材售价（总）</div><div class=\"ir-value\" id=\"r2_sheetTotalPrice\">297</div><div class=\"ir-unit\">元</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">板材利润率（使用率100%时）</div><div class=\"ir-value\" id=\"r2_profitRate\">10.5</div><div class=\"ir-unit\">%</div></div>\n    </div>\n\n    <!-- 2.3 后加工价格计算 -->\n    <div class=\"sub-label\">后加工价格计算 <span style=\"font-weight:400; color:var(--gray-400);\">(勾选启用，价格可改)</span></div>\n    <div class=\"form-grid tight\">\n      <!-- 模块3内\"自动带入\"的尺寸/数量/板材单价：隐藏显示，但保留 id 给 calcStep3 读取 -->\n      <div style=\"display:none;\">\n        <div class=\"form-group\">\n          <label>长</label>\n          <input type=\"number\" class=\"form-control auto\" id=\"s3_length\" value=\"300\" oninput=\"calcAll()\">\n        </div>\n        <div class=\"form-group\">\n          <label>宽</label>\n          <input type=\"number\" class=\"form-control auto\" id=\"s3_width\" value=\"200\" oninput=\"calcAll()\">\n        </div>\n        <div class=\"form-group\">\n          <label>高</label>\n          <input type=\"number\" class=\"form-control auto\" id=\"s3_height\" value=\"100\" oninput=\"calcAll()\">\n        </div>\n        <div class=\"form-group\">\n          <label>板材单价</label>\n          <input type=\"number\" class=\"form-control auto\" id=\"s3_sheetPrice\" value=\"0.30\" oninput=\"calcAll()\">\n        </div>\n      </div>\n    </div>\n\n    <div class=\"cb-grid\" id=\"cb_grid\">\n      <label class=\"cb-item\" data-key=\"nail\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">普通钉</span>\n        <input type=\"number\" id=\"s3p_nail\" value=\"0.5\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"rivet\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">铆钉</span>\n        <input type=\"number\" id=\"s3p_rivet\" value=\"1\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"silkprint\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">丝印(2面单色)</span>\n        <input type=\"number\" id=\"s3p_silkprint\" value=\"0.5\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"handle\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">把手</span>\n        <input type=\"number\" id=\"s3p_handle\" value=\"1.2\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"velcro\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">魔术贴(上下+4钉)</span>\n        <input type=\"number\" id=\"s3p_velcro\" value=\"5\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n    </div>\n\n    <!-- 骨架箱三合一行 -->\n    <div class=\"cb-trio\">\n      <label class=\"cb-item\" data-key=\"fiber\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">纤维胶</span>\n        <input type=\"number\" id=\"s3p_fiber\" value=\"0.5\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"velcro_corner\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">魔术贴角(4角)</span>\n        <input type=\"number\" id=\"s3p_velcro_corner\" value=\"1\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"skeleton_corner\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">骨架箱(4个顶角)</span>\n        <input type=\"number\" id=\"s3p_skeletonCorner\" value=\"3.4\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item cb-item-stack\" data-key=\"skeleton_edge\">\n        <div class=\"cb-row\">\n          <input type=\"checkbox\" onchange=\"calcAll()\">\n          <span class=\"cb-text\">骨架箱(上边条)</span>\n          <input type=\"number\" id=\"s3_skeleton_edge\" value=\"0\" oninput=\"onSkeletonEdgeInput()\">\n          <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n        </div>\n        <div class=\"cb-row2\">\n          <span class=\"auto-tag auto\" id=\"s3_skeleton_edge_tag\">≈2×(长+宽) 自动</span>\n        </div>\n      </label>\n    </div>\n\n    <div class=\"cb-grid\" id=\"cb_grid2\">\n      <label class=\"cb-item\" data-key=\"clip\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">卡夹(11.2×9.2cm+4钉)</span>\n        <input type=\"number\" id=\"s3p_clip\" value=\"1.5\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n      <label class=\"cb-item\" data-key=\"labor\">\n        <input type=\"checkbox\" onchange=\"calcAll()\">\n        <span class=\"cb-text\">人工</span>\n        <input type=\"number\" id=\"s3p_labor\" value=\"0\" oninput=\"calcAll()\">\n        <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n      </label>\n    </div>\n\n    <div style=\"display:flex; align-items:center; gap:8px; margin-bottom:8px;\">\n      <button class=\"add-cb-btn\" onclick=\"addCustomCheckbox()\">+ 添加工序</button>\n      <span style=\"font-size:11px; color:var(--gray-400);\">自定义工序可修改描述和价格</span>\n    </div>\n    <div class=\"cb-grid\" id=\"cb_custom_grid\"></div>\n\n    <!-- 后加工计算过程 -->\n    <div class=\"sub-label\">计算过程</div>\n    <div class=\"calc-process\" id=\"r3_process\"></div>\n\n    <div class=\"inline-results\">\n      <div class=\"ir-item warn\"><div class=\"ir-label\">后加工费用合计</div><div class=\"ir-value\" id=\"r3_processingTotal\">0.00</div><div class=\"ir-unit\">元</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">成品价格（单）</div><div class=\"ir-value\" id=\"r3_productUnitPrice\">0.00</div><div class=\"ir-unit\">元</div></div>\n      <div class=\"ir-item\"><div class=\"ir-label\">数量</div><div class=\"ir-value\" id=\"r3_quantity\">0</div><div class=\"ir-unit\">个</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">成品价格（总）</div><div class=\"ir-value\" id=\"r3_productTotalPrice\">0.00</div><div class=\"ir-unit\">元</div></div>\n    </div>\n\n    <!-- 2.4 附加费用计算 -->\n    <div class=\"sub-label\">附加费用计算</div>\n    <div class=\"form-grid tight\">\n      <div class=\"form-group\">\n        <label>运费 <span class=\"unit\">元</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s4_shipping\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>刀模费 <span class=\"unit\">元</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s4_die\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>丝网费 <span class=\"unit\">元</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s4_screen\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group fg-span2\">\n        <label>零头修正（数量少于1000，需修正） <span class=\"unit\">%</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s4_fractionAdj\" value=\"1\" oninput=\"calcAll()\">\n      </div>\n      <div class=\"form-group\">\n        <label>价格修正 <span class=\"unit\">元</span></label>\n        <input type=\"number\" class=\"form-control\" id=\"s4_priceAdj\" value=\"0\" oninput=\"calcAll()\">\n      </div>\n    </div>\n\n    <div class=\"sub-label\">计算过程</div>\n    <div class=\"calc-process\" id=\"r4_process\"></div>\n\n    <div class=\"inline-results\">\n      <div class=\"ir-item warn\"><div class=\"ir-label\">(运费+刀模费+丝网费)/数量</div><div class=\"ir-value\" id=\"r4_perUnitExtra\">0.000</div><div class=\"ir-unit\">元/个</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">最终报价（单）</div><div class=\"ir-value\" id=\"r4_finalUnitPrice\">0.30</div><div class=\"ir-unit\">元/个</div></div>\n      <div class=\"ir-item info\"><div class=\"ir-label\">数量</div><div class=\"ir-value\" id=\"r4_quantity\">0</div><div class=\"ir-unit\">个</div></div>\n      <div class=\"ir-item warn\"><div class=\"ir-label\">最终报价（总）</div><div class=\"ir-value\" id=\"r4_finalTotalPrice\">0.00</div><div class=\"ir-unit\">元</div></div>\n    </div>\n  </div>\n</div>\n\n</div><!-- end left-col -->\n\n<!-- ==================== Right: Summary Panel ==================== -->\n<div class=\"right-col\">\n  <div class=\"summary-panel\">\n    <div class=\"summary-header\">\n      <h2>最终报价</h2>\n      <p>数据自动从左侧汇总</p>\n    </div>\n    <div class=\"summary-body\">\n\n      <div class=\"quote-stack\">\n\n        <div class=\"quote-row\">\n          <div class=\"qr-label\">是否含税</div>\n          <div class=\"qr-value\" id=\"sum_taxStatus\">否</div>\n        </div>\n\n        <div class=\"quote-row hl\">\n          <div class=\"qr-label\">最终报价（单）</div>\n          <div class=\"qr-value\" id=\"sum_finalUnit\">0.30 元</div>\n        </div>\n\n        <div class=\"quote-row\">\n          <div class=\"qr-label\">数量</div>\n          <div class=\"qr-value\" id=\"sum_quantity\">1000</div>\n        </div>\n\n        <div class=\"quote-row hl\">\n          <div class=\"qr-label\">最终报价（总）</div>\n          <div class=\"qr-value\" id=\"sum_finalTotal\">300 元</div>\n        </div>\n\n        <div class=\"quote-row hl\">\n          <div class=\"qr-label\">总体积</div>\n          <div class=\"qr-value\" id=\"sum_volume\">0.00 m³</div>\n        </div>\n\n        <div class=\"quote-row hl\">\n          <div class=\"qr-label\">总吨数</div>\n          <div class=\"qr-value\" id=\"sum_tons\">0.00 T</div>\n        </div>\n\n      </div>\n\n      <div style=\"margin-top:12px; font-size:11px; color:var(--gray-400); text-align:center;\">\n        左侧修改后自动重算\n      </div>\n    </div>\n  </div>\n</div>\n\n</div><!-- end main-wrap -->\n\n<script>\n// ==================== State ====================\nconst state = {\n  style: '板材',\n  boxCat: false,\n  caseCat: false,\n  caseDimType: '',\n  boxDimType: '',\n  dimType: '',\n  materialType: '普通',\n  lastBoxStyle: '',   // 记住上次选过的具体箱型，切走再切回时恢复\n  lastCaseStyle: ''   // 记住上次选过的盒子子样式，切走再切回时恢复\n};\n\n// ===== 箱类样式统一名单（唯一定义处；以后新增箱型只改这一行）=====\n// 含\"高\"维度、需要选外尺/内尺、走箱类体量公式的样式，全部在此登记\nconst BOX_STYLES = ['纸箱式','插底式','焊底式','骨架箱','全包式','四拼式','投票箱'];\n\n// 四拼式：总立方数系数（总立方数 = 单产品面积×厚度×本系数×数量÷1000）\n// 已由品牌方确认 = 1.25（与纸箱式/插底式/全包式同档）；单产品面积本身已按\"2 片板材1 + 2 片板材2\"计足用料\nconst SI_PIN_VOL_COEF = 1.25;\n\n// ===== 鉴权初始化（密码登录）=====\ndocument.addEventListener('DOMContentLoaded', ()=>{\n  const overlay = document.getElementById('authOverlay');\n  if(!sessionStorage.getItem('role')) sessionStorage.setItem('role', 'employee');\n  overlay.style.display = 'none';\n  applyRole();\n});\n\n// 按配方类型保存用户自定义价格（切换配方时优先用这些值，而不是 materialDefaults 的默认值）\n// 结构：{ '新料+透明母料': { newPrice: 9500, masterPrice: 4000, ... }, ... }\nconst materialPrices = {};\n\nconst materialDefaults = {\n  '普通':         { masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 2000, specialPrice: 0,     fixedCost: 1700 },\n  '回料+母料':    { masterRatio: 0,  specialRatio: 0,    newPrice: 4300, masterPrice: 2000, specialPrice: 0,     fixedCost: 1700 },\n  '新料+透明母料':{ masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 3800, specialPrice: 0,     fixedCost: 1700 },\n  '防静电':       { masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 2000, specialPrice: 10500, fixedCost: 1700 },\n  '导电':         { masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 2000, specialPrice: 10500, fixedCost: 1700 },\n  '耐低温':       { masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 2000, specialPrice: 14000, fixedCost: 1700 },\n  '阻燃':         { masterRatio: 0,  specialRatio: 0,    newPrice: 9000, masterPrice: 2000, specialPrice: 24000, fixedCost: 1700 }\n};\n\n// ==================== Selectors ====================\nfunction syncStyleUI(){\n  const boxSub = document.getElementById('s1_box_sub_row');\n  const dimRow = document.getElementById('s1_dimtype_row');\n  const boxStyles = BOX_STYLES;\n  const isBoxSub = boxStyles.includes(state.style);\n  boxSub.style.display = (isBoxSub || state.boxCat) && state.style !== '投票箱' ? '' : 'none';\n  document.getElementById('s1_case_sub_row').style.display = state.caseCat || state.style === '投票箱' ? '' : 'none';\n  dimRow.style.display = state.boxCat || state.caseCat ? 'flex' : 'none';\n  const isBallotBox = state.style === '投票箱';\n  const isCase = state.caseCat || isBallotBox;\n  if(isCase) state.dimType = state.caseDimType;\n  else if(state.boxCat) state.dimType = state.boxDimType;\n  dimRow.querySelectorAll('.type-chip').forEach(chip => {\n    chip.style.display = isCase && chip.dataset.dim === '内尺' ? 'none' : '';\n    chip.classList.toggle('active', chip.dataset.dim === state.dimType);\n  });\n  updateHeightVisibility();\n  // 使用率始终显示；圆盘样式下为只读计算值（readonly 由 calcStep1 控制），其余样式可编辑\n  const urGroup = document.getElementById('s1_usageRate_group');\n  if(urGroup) urGroup.style.display = '';\n  const styleChips = document.querySelectorAll('#s1_style_row .type-chip, #s1_box_sub_row .type-chip, #s1_case_sub_row .type-chip');\n  styleChips.forEach(c=>c.classList.remove('active'));\n  if(state.style){\n    const chip = document.querySelector('#s1_style_row .type-chip[data-style=\"'+state.style+'\"], #s1_box_sub_row .type-chip[data-style=\"'+state.style+'\"], #s1_case_sub_row .type-chip[data-style=\"'+state.style+'\"]');\n    if(chip) chip.classList.add('active');\n    if(isBoxSub){\n      const parentStyle = isBallotBox ? '盒子' : '箱子';\n      const p = document.querySelector('#s1_style_row .type-chip[data-style=\"'+parentStyle+'\"]');\n      if(p) p.classList.add('active');\n    }\n  } else if(state.caseCat){\n    const p = document.querySelector('#s1_style_row .type-chip[data-style=\"盒子\"]');\n    if(p) p.classList.add('active');\n  } else if(state.boxCat){\n    const p = document.querySelector('#s1_style_row .type-chip[data-style=\"箱子\"]');\n    if(p) p.classList.add('active');\n  }\n}\n\nfunction selectStyle(el){\n  const s = el.dataset.style;\n  const boxStyles = BOX_STYLES;\n  if(s==='盒子'){\n    const willShow = document.getElementById('s1_case_sub_row').style.display === 'none';\n    state.caseCat = willShow;\n    state.style = willShow ? state.lastCaseStyle : '';\n    state.boxCat = BOX_STYLES.includes(state.style);\n    syncStyleUI();\n    calcAll();\n    return;\n  }\n  if(s==='箱子'){\n    state.caseCat = false;\n    // 切换\"箱子\"大类展开；再次展开时恢复上次选过的具体箱型\n    const boxSub = document.getElementById('s1_box_sub_row');\n    const willShow = boxSub.style.display==='none';\n    if(willShow){\n      state.boxCat = true;\n      state.style = state.lastBoxStyle || '';   // 恢复上次具体箱型；无则仅高亮\"箱子\"大类\n    } else {\n      state.boxCat = false;\n      if(boxStyles.includes(state.style)) state.style = ''; // 收起时若已选具体箱型则清空\n    }\n    syncStyleUI();\n    calcAll();\n    return;\n  }\n  state.style = s;\n  state.caseCat = s === '投票箱';\n  if(state.caseCat) state.lastCaseStyle = s;\n  if(boxStyles.includes(s) && s !== '投票箱') state.lastBoxStyle = s;   // 记住选过的具体箱型\n  state.boxCat = boxStyles.includes(s);  // 选非箱类(板材/圆盘)时务必置 false，否则子行残留\n  syncStyleUI();\n  calcAll();\n}\n\nfunction selectDimType(el) {\n  el.parentElement.querySelectorAll('.type-chip').forEach(c => c.classList.remove('active'));\n  el.classList.add('active');\n  state.dimType = state.caseCat || state.style === '投票箱' ? '外尺' : el.dataset.dim;\n  if(state.caseCat || state.style === '投票箱') state.caseDimType = state.dimType;\n  else if(state.boxCat) state.boxDimType = state.dimType;\n  calcAll();\n}\n\n// 仅箱类样式（见 BOX_STYLES）存在\"高\"维度；未选样式或选 板材/圆盘 时隐藏\"高\"\nfunction isHeightHidden(){\n  return !BOX_STYLES.includes(state.style);\n}\nfunction updateHeightVisibility(){\n  const g = document.getElementById('s1_height_group');\n  if(g) g.style.display = isHeightHidden() ? 'none' : '';\n}\n\nfunction selectMaterialType(el) {\n  // ===== 切换前：先保存当前配方的价格和比例到 materialPrices =====\n  const oldType = state.materialType;\n  if(oldType){\n    materialPrices[oldType] = {\n      newPrice:     parseFloat(document.getElementById('s2_newPrice').value)     || 0,\n      masterPrice:  parseFloat(document.getElementById('s2_masterPrice').value)  || 0,\n      specialPrice: parseFloat(document.getElementById('s2_specialPrice').value) || 0,\n      fixedCost:    parseFloat(document.getElementById('s2_fixedCost').value)    || 0,\n      masterRatio:  parseFloat(document.getElementById('s2_masterRatio').value)  || 0,\n      specialRatio: parseFloat(document.getElementById('s2_specialRatio').value) || 0,\n      _userSet: Array.from(document.querySelectorAll('[data-user-set=\"1\"]')).map(el=>el.id).filter(Boolean)\n    };\n  }\n\n  document.querySelectorAll('#s2_type_row .type-chip').forEach(c => c.classList.remove('active'));\n  el.classList.add('active');\n  state.materialType = el.dataset.type;\n  const d = materialDefaults[state.materialType];\n  if(!d){\n    showToast('未找到「'+state.materialType+'」的默认参数');\n    return;\n  }\n  // 比例字段：优先用 materialPrices 里存过的自定义比例，没有则用默认值\n  const savedPrices = materialPrices[state.materialType] || {};\n  document.getElementById('s2_masterRatio').value = savedPrices.masterRatio ?? d.masterRatio;\n  document.getElementById('s2_masterRatio').removeAttribute('data-user-set');\n  document.getElementById('s2_specialRatio').value = savedPrices.specialRatio ?? d.specialRatio;\n  document.getElementById('s2_specialRatio').removeAttribute('data-user-set');\n\n  // 价格字段：\n  // 1. 优先用 materialPrices[当前配方] 里存过的自定义价格\n  // 2. 没有则用 materialDefaults 里的代码默认值\n  const priceMap = [\n    ['s2_newPrice',    savedPrices.newPrice    ?? d.newPrice],\n    ['s2_masterPrice', savedPrices.masterPrice ?? d.masterPrice],\n    ['s2_specialPrice',savedPrices.specialPrice?? d.specialPrice],\n    ['s2_fixedCost',   savedPrices.fixedCost   ?? d.fixedCost]\n  ];\n  priceMap.forEach(([id, val]) => {\n    const f = document.getElementById(id);\n    if(!f) return;\n    f.value = val;\n    // 切回此配方时，恢复之前保存的用户价格标记（如果有）\n    if(savedPrices._userSet && savedPrices._userSet.indexOf(id) >= 0){\n      f.setAttribute('data-user-set', '1');\n    } else {\n      f.removeAttribute('data-user-set');\n    }\n  });\n  calcAll();\n}\n\n// ==================== Master Calc ====================\nfunction calcAll() {\n  // 是否含税=是 时显示税点输入框，否则隐藏\n  document.getElementById('s1_taxRate_group').style.display = (document.getElementById('s1_tax').value === '是') ? '' : 'none';\n\n  // 原料配方显隐逻辑\n  const mt = state.materialType;\n  const showMaster = (mt === '普通' || mt === '回料+母料' || mt === '新料+透明母料' || mt === '防静电' || mt === '导电' || mt === '耐低温' || mt === '阻燃');\n  const showSpecial = (mt === '防静电' || mt === '导电' || mt === '耐低温' || mt === '阻燃');\n  const showNew = showMaster;  // 新料与母料同条件出现\n  document.getElementById('grp_newPrice').style.display = showNew ? '' : 'none';\n  document.getElementById('grp_newRatio').style.display = showNew ? '' : 'none';\n  document.getElementById('grp_masterPrice').style.display = showMaster ? '' : 'none';\n  document.getElementById('grp_masterRatio').style.display = showMaster ? '' : 'none';\n  document.getElementById('grp_specialPrice').style.display = showSpecial ? '' : 'none';\n  document.getElementById('grp_specialRatio').style.display = showSpecial ? '' : 'none';\n\n  // 新料比例 = 1 - 母料比例 - 特殊料比例（只读同步）\n  const nr = 100 - +val('s2_masterRatio') - +val('s2_specialRatio');\n  document.getElementById('s2_newRatio').value = fmt(nr, 1);\n  // Step 1\n  const r1 = calcStep1();\n  // Step 2\n  const r2 = calcStep2(r1);\n  // Auto-sync to step 3\n  document.getElementById('s3_sheetPrice').value = fmt(r2.V, 2);\n  document.getElementById('s3_length').value = document.getElementById('s1_length').value;\n  document.getElementById('s3_width').value = document.getElementById('s1_width').value;\n  document.getElementById('s3_height').value = document.getElementById('s1_height').value;\n  // Step 3\n  const r3 = calcStep3(r2);\n  // Auto-sync: 成品报价和数量直接从 Step3/Step1 取值（不再用中间输入框）\n  // Step 4\n  const r4 = calcStep4(r3);\n  // Summary（必填已取消，始终出报价）\n  updateSummary(r1, r2, r3, r4);\n}\n\n// ==================== Step 1 ====================\nlet manualUsageRate = 100;   // 非圆盘样式的手动使用率（默认100）\nlet urAutoSet = false;        // 圆盘样式下使用率是否被改写为自动计算值\n\nfunction calcStep1() {\n  const A = +val('s1_thickness'), B = +val('s1_weight'), E = +val('s1_length'), F = +val('s1_width'), G = isHeightHidden() ? 1 : +val('s1_height'), H = +val('s1_quantity');\n  const urInput = document.getElementById('s1_usageRate');\n  let ur;\n  if(state.style==='圆盘'){\n    // 圆盘：使用率是按公式算出的结果，只读、不允许人工修改；面积直接按环面积计算，不乘使用率\n    urInput.readOnly = true; urInput.classList.add('auto');\n    ur = 1;\n  } else {\n    urInput.readOnly = false; urInput.classList.remove('auto');\n    if(urAutoSet){ urInput.value = manualUsageRate; urAutoSet = false; }  // 离开圆盘后恢复手动值\n    manualUsageRate = val('s1_usageRate') || 100;\n    ur = manualUsageRate/100;\n  }\n  let I, J, K, L, M, N, Im, Jm, Ia, Ja, Loff, Woff;\n  const proc = [];\n  const urPct = fmt(ur*100,0);\n  const processBox = document.getElementById('r1_process');\n  const b2 = document.getElementById('r1_b2'), bw2 = document.getElementById('r1_bw2');\n  function hideBoard2(){\n    text('r1_sheetL_label','板材长'); text('r1_sheetW_label','板材宽');\n    text('r1_sheetL2','—'); text('r1_sheetW2','—');\n    b2.style.display='none'; bw2.style.display='none';\n  }\n  function showBoard2(lbl1,lbl2){\n    text('r1_sheetL_label',lbl1); text('r1_sheetW_label',lbl2);\n    b2.style.display=''; bw2.style.display='';\n  }\n\n  // 未选择产品样式：返回安全零值，避免后续计算出现 NaN\n  if(!state.style){\n    text('r1_sheetL','—'); text('r1_sheetW','—'); text('r1_sheetL2','—'); text('r1_sheetW2','—');\n    text('r1_area','—'); text('r1_volume','—'); text('r1_tons','—');\n    processBox.innerHTML = '';\n    hideBoard2();\n    return {A,B,E,F,G,H, I:0,J:0,K:0,L:0,M:0,N:0};\n  }\n  // 箱类样式未选内/外尺：清空过程展示，等用户选了再算\n  const _needDim = BOX_STYLES.includes(state.style);\n  if(_needDim && !state.dimType){\n    text('r1_sheetL','—'); text('r1_sheetW','—'); text('r1_sheetL2','—'); text('r1_sheetW2','—');\n    text('r1_area','—'); text('r1_volume','—'); text('r1_tons','—');\n    const dimensionHint = state.style === '投票箱' ? '请先选择「外尺」' : '请先选择「外尺」或「内尺」';\n    processBox.innerHTML='<div class=\"proc-hint\" style=\"color:#9ca3af;padding:8px;\">'+dimensionHint+'</div>';\n    hideBoard2();\n    return {A,B,E,F,G,H, I:0,J:0,K:0,L:0,M:0,N:0};\n  }\n\n  const isInner = (state.dimType==='内尺');\n  switch(state.style) {\n    case '板材':\n      I=E; J=F; K=1; L=I*J*K/1e6*ur; M=L*A*H/1e3; N=L*B*H/1e6;\n      proc.push(cpLine('板材长', '长', fmt(E,0), fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '宽', fmt(F,0), fmt(J,1)+' mm'));\n      proc.push(cpLine('单产品面积', '长×宽×使用率÷10⁶', fmt(E,0)+'×'+fmt(F,0)+'×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '圆盘':\n      I=E+10; J=E+10;\n      K=Math.PI*((E/2)**2-(F/2)**2)/(E*E);   // 使用率 = π×((外直径/2)² − (内直径/2)²) ÷ 外直径²  【公式计算结果，只读】\n      L=Math.PI*((E/2)**2-(F/2)**2)/1e6;      // 单产品面积 = π×((外直径/2)² − (内直径/2)²) ÷ 1e6\n      M=E*E*A*H/1e9; N=L*B*H/1e6;            // 圆盘总立方数 = 外直径²×厚度×数量÷1e9\n      urInput.value = fmt(K*100,1); urAutoSet = true;   // 回填计算得到的使用率（只读，不允许修改）\n      proc.push(cpLine('板材长', '外直径 + 10', fmt(E,0)+'+10', fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '外直径 + 10', fmt(E,0)+'+10', fmt(J,1)+' mm'));\n      proc.push(cpLine('使用率', '(π×(外直径/2)² − π×(内直径/2)²) ÷ 外直径²', '(π×'+fmt(E/2,1)+'²−π×'+fmt(F/2,1)+'²)÷'+fmt(E,0)+'²', fmt(K*100,1)+' %'));\n      proc.push(cpLine('单产品面积', '(π×(外直径/2)² − π×(内直径/2)²) ÷ 10⁶', '(π×'+fmt(E/2,1)+'²−π×'+fmt(F/2,1)+'²)÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '纸箱式':\n      Loff = isInner ? 35 : 10; Woff = isInner ? 60 : 45;  // 板材长/宽 加放量(内尺含咬口)\n      I=F+G+Loff; J=E+F+Woff;\n      K=1; L=I*J*2*K/1e6*ur; M=L*A*1.25*H/1e3; N=L*B*H/1e6;\n      proc.push(cpLine('板材长', '宽 + 高 + '+Loff, fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '长 + 宽 + '+Woff, fmt(E,0)+'+'+fmt(F,0)+'+'+Woff, fmt(J,1)+' mm'));\n      proc.push(cpLine('单产品面积', '板材长×板材宽×2×使用率÷10⁶', fmt(I,1)+'×'+fmt(J,1)+'×2×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '插底式':\n      Loff = isInner ? 95 : 70; Woff = isInner ? 60 : 45;\n      I=F+G+Loff; J=E+F+Woff;\n      K=1; L=I*J*2*K/1e6*ur; M=L*A*1.25*H/1e3; N=L*B*H/1e6;\n      proc.push(cpLine('板材长', '宽 + 高 + '+Loff, fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '长 + 宽 + '+Woff, fmt(E,0)+'+'+fmt(F,0)+'+'+Woff, fmt(J,1)+' mm'));\n      proc.push(cpLine('单产品面积', '板材长×板材宽×2×使用率÷10⁶', fmt(I,1)+'×'+fmt(J,1)+'×2×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '焊底式':\n      Loff = isInner ? 35 : 10; Woff = isInner ? 60 : 45;\n      Im=F+G+Loff; Jm=E+F+Woff; Ia=1.5*F+G+Loff; Ja=E+F+Woff;\n      K=1; I=Im; J=Jm; L=(Im*Jm+Ia*Ja)*K/1e6*ur; M=L*A*2*H/1e3; N=L*B*H/1e6;\n      proc.push(cpHead('板材1'));\n      proc.push(cpLine('板材长①', '宽 + 高 + '+Loff, fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(Im,1)+' mm'));\n      proc.push(cpLine('板材宽①', '长 + 宽 + '+Woff, fmt(E,0)+'+'+fmt(F,0)+'+'+Woff, fmt(Jm,1)+' mm'));\n      proc.push(cpHead('板材2'));\n      proc.push(cpLine('板材长②', '1.5×宽 + 高 + '+Loff, '1.5×'+fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(Ia,1)+' mm'));\n      proc.push(cpLine('板材宽②', '长 + 宽 + '+Woff, fmt(E,0)+'+'+fmt(F,0)+'+'+Woff, fmt(Ja,1)+' mm'));\n      proc.push(cpLine('单产品面积', '(板材长①×板材宽① + 板材长②×板材宽②)×使用率÷10⁶', '('+fmt(Im,1)+'×'+fmt(Jm,1)+'+'+fmt(Ia,1)+'×'+fmt(Ja,1)+')×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      showBoard2('板材长①','板材宽①');\n      text('r1_sheetL2', fmt(Ia,1)); text('r1_sheetW2', fmt(Ja,1));\n      break;\n    case '骨架箱':\n      Loff = isInner ? 25 : 10; Woff = isInner ? 25 : 10;\n      I=F+2*G+Loff; J=(0.5*F<G)?(E+2*G+Loff):(E+F+Woff);\n      K=1; L=I*J*K/1e6*ur; M=E*F*G*H/1e9; N=L*B*H/1e6;\n      proc.push(cpLine('板材长', '宽 + 2×高 + '+Loff, fmt(F,0)+'+2×'+fmt(G,0)+'+'+Loff, fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '长方向取值 '+(0.5*F<G?('长 + 2×高 + '+Loff):('长 + 宽 + '+Woff)), (0.5*F<G?(fmt(E,0)+'+2×'+fmt(G,0)+'+'+Loff):(fmt(E,0)+'+'+fmt(F,0)+'+'+Woff)), fmt(J,1)+' mm'));\n      proc.push(cpLine('单产品面积', '板材长×板材宽×使用率÷10⁶', fmt(I,1)+'×'+fmt(J,1)+'×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '全包式':\n      Loff = isInner ? 35 : 10; Woff = isInner ? 60 : 45;\n      I=2*F+G+Loff; J=E+F+Woff;\n      K=1; L=I*J*2*K/1e6*ur; M=L*A*1.25*H/1e3; N=L*B*H/1e6;\n      proc.push(cpLine('板材长', '2×宽 + 高 + '+Loff, '2×'+fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(I,1)+' mm'));\n      proc.push(cpLine('板材宽', '长 + 宽 + '+Woff, fmt(E,0)+'+'+fmt(F,0)+'+'+Woff, fmt(J,1)+' mm'));\n      proc.push(cpLine('单产品面积', '板材长×板材宽×2×使用率÷10⁶', fmt(I,1)+'×'+fmt(J,1)+'×2×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      hideBoard2();\n      break;\n    case '投票箱':\n      Im=G+2*F+70; Jm=E+10; Ia=G+100; Ja=E+2*F+70;\n      K=1; I=Im; J=Jm;\n      L=(Im*Jm+Ia*Ja)/1e6*ur;\n      M=L*A*1.25*H/1e3; N=L*B*H/1e6;\n      proc.push(cpHead('板材1'));\n      proc.push(cpLine('板材长①', '高 + 2×宽 + 70', fmt(G,0)+'+2×'+fmt(F,0)+'+70', fmt(Im,1)+' mm'));\n      proc.push(cpLine('板材宽①', '长 + 10', fmt(E,0)+'+10', fmt(Jm,1)+' mm'));\n      proc.push(cpHead('板材2'));\n      proc.push(cpLine('板材长②', '高 + 100', fmt(G,0)+'+100', fmt(Ia,1)+' mm'));\n      proc.push(cpLine('板材宽②', '长 + 2×宽 + 70', fmt(E,0)+'+2×'+fmt(F,0)+'+70', fmt(Ja,1)+' mm'));\n      proc.push(cpLine('单产品面积', '(板材长①×板材宽① + 板材长②×板材宽②)×使用率÷10⁶', '('+fmt(Im,1)+'×'+fmt(Jm,1)+'+'+fmt(Ia,1)+'×'+fmt(Ja,1)+')×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      showBoard2('板材长①','板材宽①');\n      text('r1_sheetL2', fmt(Ia,1)); text('r1_sheetW2', fmt(Ja,1));\n      break;\n    case '四拼式':\n      // 1 个箱子 = 2 片板材1 + 2 片板材2（板材1+板材2 拼起来是半个箱子）\n      // 加放量：板材长 内尺+35 / 外尺+10；板材宽② 内尺+25 / 外尺+10；板材宽① 内外尺均为 长+90\n      Loff = isInner ? 35 : 10; Woff = isInner ? 25 : 10;\n      Im = F+G+Loff; Jm = E+90; Ia = Im; Ja = F+Woff;\n      K=1; I=Im; J=Jm;\n      L=(Im*Jm*2 + Ia*Ja*2)*K/1e6*ur;\n      M=L*A*SI_PIN_VOL_COEF*H/1e3; N=L*B*H/1e6;\n      proc.push(cpHead('板材1'));\n      proc.push(cpLine('板材长①', '宽 + 高 + '+Loff, fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(Im,1)+' mm'));\n      proc.push(cpLine('板材宽①', '长 + 90', fmt(E,0)+'+90', fmt(Jm,1)+' mm'));\n      proc.push(cpHead('板材2'));\n      proc.push(cpLine('板材长②', '宽 + 高 + '+Loff, fmt(F,0)+'+'+fmt(G,0)+'+'+Loff, fmt(Ia,1)+' mm'));\n      proc.push(cpLine('板材宽②', '宽 + '+Woff, fmt(F,0)+'+'+Woff, fmt(Ja,1)+' mm'));\n      proc.push(cpLine('单产品面积', '(板材长①×板材宽①×2 + 板材长②×板材宽②×2)×使用率÷10⁶', '('+fmt(Im,1)+'×'+fmt(Jm,1)+'×2+'+fmt(Ia,1)+'×'+fmt(Ja,1)+'×2)×'+urPct+'%÷1000000', fmt(L,3)+' ㎡'));\n      showBoard2('板材长①','板材宽①');\n      text('r1_sheetL2', fmt(Ia,1)); text('r1_sheetW2', fmt(Ja,1));\n      break;\n  }\n\n  if(state.style==='骨架箱'){\n    proc.push(cpLine('总立方数', '长×宽×高×数量÷1e9', fmt(E,0)+'×'+fmt(F,0)+'×'+fmt(G,0)+'×'+fmt(H,0)+'÷1e9', fmt(M,2)+' m³'));\n  } else if(state.style==='圆盘'){\n    proc.push(cpLine('总立方数', '外直径²×厚度×数量÷1e9', fmt(E,0)+'²×'+fmt(A,1)+'×'+fmt(H,0)+'÷1e9', fmt(M,2)+' m³'));\n  } else if(state.style==='焊底式'){\n    proc.push(cpLine('总立方数', '单产品面积×厚度×2×数量÷1000', fmt(L,4)+'×'+fmt(A,1)+'×2×'+fmt(H,0)+'÷1000', fmt(M,2)+' m³'));\n  } else if(state.style==='四拼式'){\n    proc.push(cpLine('总立方数', '单产品面积×厚度×'+SI_PIN_VOL_COEF+'×数量÷1000', fmt(L,4)+'×'+fmt(A,1)+'×'+SI_PIN_VOL_COEF+'×'+fmt(H,0)+'÷1000', fmt(M,2)+' m³'));\n  } else if(state.style==='板材'){\n    proc.push(cpLine('总立方数', '单产品面积×厚度×数量÷1000', fmt(L,4)+'×'+fmt(A,1)+'×'+fmt(H,0)+'÷1000', fmt(M,2)+' m³'));\n  } else {\n    // 纸箱式/插底式/全包式：单产品面积×厚度×1.25×数量÷1000\n    proc.push(cpLine('总立方数', '单产品面积×厚度×1.25×数量÷1000', fmt(L,4)+'×'+fmt(A,1)+'×1.25×'+fmt(H,0)+'÷1000', fmt(M,2)+' m³'));\n  }\n  proc.push(cpLine('总吨数', '单产品面积×克重×数量÷10⁶', fmt(L,4)+'×'+fmt(B,1)+'×'+fmt(H,0)+'÷1000000', fmt(N,2)+' T'));\n  text('r1_sheetL', fmt(I,1)); text('r1_sheetW', fmt(J,1));\n  text('r1_area', fmt(L,3)); text('r1_volume', fmt(M,2)); text('r1_tons', fmt(N,2));\n  processBox.innerHTML = proc.join('');\n  return {A,B,E,F,G,H,I,J,K,L,M,N,Im,Jm,Ia,Ja,ur};\n}\n\n// ==================== Step 2 ====================\nfunction calcStep2(r1 = calcStep1()) {\n  const A=document.getElementById('s1_tax').value,\n    B=+val('s1_taxRate')/100,\n    E=+val('s1_weight'),\n    F=+val('s2_masterRatio')/100,\n    G=+val('s2_specialRatio')/100,\n    M=+val('s1_quantity'),\n    N=+val('s2_newPrice'), O=+val('s2_masterPrice'), P=+val('s2_specialPrice'),\n    Q=+val('s2_fixedCost'), R=+val('s2_profit');\n\n  // 中间结果保留完整精度，仅在展示时四舍五入。\n  const area = r1.L;\n  let S = (A==='是') ? F*O+G*P+(1-F-G)*N : (F*O+G*P+(1-F-G)*N)*0.93;\n  let T = (A==='是') ? (Q+S+R)*(1+B) : S+Q+R;\n  const U=T*E/1e6;                  // 平方价 = 原料售价 × 克重 ÷ 1e6\n  const V = U*area;                // 板材售价（单）= 单产品面积 × 平方价\n  const W = V*M;                    // 板材售价（总）= 板材售价（单）× 数量\n  // 板材利润率（使用率100%时）：\n  // 不含税 → 原料利润/原料售价 = R/T\n  // 含税 → (原料售价×0.94−原来成本−固定成本)/原料售价 = (T×0.94−S−Q)/T\n  const numerator = (A==='是') ? (T*0.94 - S - Q) : R;\n  let X = (T !== 0) ? numerator/T : 0;\n\n  // ---- 计算过程展示 ----\n  const proc2 = [];\n  const FP = fmt(F*100,0), GP = fmt(G*100,0), RFP = fmt((1-F-G)*100,0);\n  // 原料成本\n  if(A==='是'){\n    proc2.push(cpLine('原料成本', '母料比例×母料价+特殊料比例×特殊料价+(1−母料比例−特殊料比例)×新料价',\n      FP+'%×'+fmt(O,0)+'+'+GP+'%×'+fmt(P,0)+'+'+RFP+'%×'+fmt(N,0), fmt(S,0)+' 元/吨'));\n  } else {\n    proc2.push(cpLine('原料成本', '(母料比例×母料价+特殊料比例×特殊料价+(1−母料比例−特殊料比例)×新料价)×0.93',\n      '('+FP+'%×'+fmt(O,0)+'+'+GP+'%×'+fmt(P,0)+'+'+RFP+'%×'+fmt(N,0)+')×0.93', fmt(S,0)+' 元/吨'));\n  }\n  // 原料售价\n  if(A==='是'){\n    proc2.push(cpLine('原料售价', '(固定成本+原料成本+原料利润)×(1+税率)',\n      '('+fmt(Q,0)+'+'+fmt(S,0)+'+'+fmt(R,0)+')×(1+'+fmt(B*100,0)+'%)', fmt(T,0)+' 元/吨'));\n  } else {\n    proc2.push(cpLine('原料售价', '原料成本+固定成本+原料利润',\n      fmt(S,0)+'+'+fmt(Q,0)+'+'+fmt(R,0), fmt(T,0)+' 元/吨'));\n  }\n  // 平方价\n  proc2.push(cpLine('平方价', '原料售价×克重÷1e6',\n    fmt(T,0)+'×'+fmt(E,0)+'÷1e6', fmt(U,2)+' 元/㎡'));\n  // 板材售价（单）\n  proc2.push(cpLine('板材售价（单）', '单产品面积×平方价',\n    fmt(area,4)+'×'+fmt(U,2), fmt(V,3)+' 元'));\n  // 板材售价（总）\n  proc2.push(cpLine('板材售价（总）', '板材售价（单）×数量',\n    fmt(V,3)+'×'+fmt(M,0), fmt(W,2)+' 元'));\n  // 板材利润率（使用率100%时）\n  if(A==='是'){\n    proc2.push(cpLine('板材利润率（使用率100%时）', '(原料售价×0.94−原料成本−固定成本)/原料售价',\n      '('+fmt(T,0)+'×0.94−'+fmt(S,0)+'−'+fmt(Q,0)+')÷'+fmt(T,0), fmt(X*100,2)+' %'));\n  } else {\n    proc2.push(cpLine('板材利润率（使用率100%时）', '原料利润/原料售价',\n      fmt(R,0)+'÷'+fmt(T,0), fmt(X*100,2)+' %'));\n  }\n  text('r2_process', '');  // 先清空再写入\n  document.getElementById('r2_process').innerHTML = proc2.join('');\n\n  text('r2_area',fmt(area,3));\n  text('r2_materialCost',fmt(S,0)); text('r2_materialPrice',fmt(T,0));\n  text('r2_sqPrice',fmt(U,2)); text('r2_sheetUnitPrice',fmt(V,3)); text('r2_sheetQty',fmt(M,0)); text('r2_sheetTotalPrice',fmt(W,2));\n  text('r2_profitRate',fmt(X*100,2));  // 板材利润率（使用率100%时），保留2位小数\n  text('r2_weight',fmt(E,1));  // 克重：同步自产品参数 s1_weight\n  return {A,B,area,S,T,U,V,W,X};\n}\n\n// ==================== Step 3 ====================\nfunction calcStep3(r2 = calcStep2()) {\n  const A=document.getElementById('s1_tax').value, B=+val('s1_taxRate')/100,\n    C=+val('s3_length'), D=+val('s3_width'), H=+val('s3_sheetPrice');\n  const G=2*(C+D)/1e3;\n\n  // 骨架箱(上边条)：默认按 2×(长+宽) 自动算，用户手动改过则保留（可清空恢复自动）\n  const seEl = document.getElementById('s3_skeleton_edge');\n  const seTag = document.getElementById('s3_skeleton_edge_tag');\n  if(seEl && seEl.getAttribute('data-user-set') !== '1'){\n    seEl.value = fmt(2*G, 2);\n    if(seTag){ seTag.textContent = '≈2×(长+宽)='+fmt(2*G,2)+' 自动'; seTag.className = 'auto-tag auto'; }\n  }\n\n  let sum=0; const details=[];\n  document.querySelectorAll('#cb_grid .cb-item, .cb-trio .cb-item, #cb_grid2 .cb-item, #cb_custom_grid .cb-item').forEach(item=>{\n    const cb=item.querySelector('input[type=\"checkbox\"]');\n    const key=item.dataset.key;\n    if(cb.checked){\n      const pi=item.querySelector('input[type=\"number\"]'); const price=pi?+pi.value||0:0;\n      sum+=price;\n      // 自定义工序用 text input 获取描述，固定工序用 .cb-text span\n      const textEl = item.querySelector('.cb-text-input') || item.querySelector('.cb-text');\n      details.push({name:textEl ? (textEl.value || textEl.textContent.trim()) : key, price});\n      item.classList.add('checked');\n    } else {\n      item.classList.remove('checked');\n    }\n  });\n\n  // 后加工费用合计：是否含税为\"是\"时按 (1+税率) 计入，否则保持各工序 raw 价之和\n  const sumAfterTax = (A==='是') ? sum*(1+B) : sum;\n  // 同步 r2 板材售价（单）= r2_sheetUnitPrice；成品价格（单）= 板材售价(单) + 加工费合计\n  const sheetUnitPrice = r2.V;\n  const productUnitPrice = sheetUnitPrice + sumAfterTax;\n\n  // 后加工计算过程（cpLine 四段式格式）\n  const proc3 = [];\n  // 后加工费用合计 = 各工序单价（工序名称）之和 = 合计金额\n  if(details.length > 0){\n    const formulaCalc = details.map(d => fmt(d.price,3)+'('+d.name+')').join('+');\n    const calcExpr = (A==='是')\n      ? '('+formulaCalc+')×(1+'+fmt(B*100,0)+'%)'\n      : formulaCalc;\n    proc3.push(cpLine('后加工费用合计', '', calcExpr, fmt(sumAfterTax,3)+' 元'));\n  } else {\n    proc3.push(cpLine('后加工费用合计', '', '0', fmt(sumAfterTax,3)+' 元'));\n  }\n  // 成品价格（单）\n  proc3.push(cpLine('成品价格（单）', '板材售价（单）+后加工费用合计',\n    fmt(sheetUnitPrice,3)+'+'+fmt(sumAfterTax,3), fmt(productUnitPrice,3)+' 元'));\n  // 成品价格（总）= 成品价格（单）× 数量\n  const quantity = +val('s1_quantity') || 0;\n  const productTotalPrice = productUnitPrice * quantity;\n\n  // 成品价格（总）计算过程\n  proc3.push(cpLine('成品价格（总）', '成品价格（单）×数量',\n    fmt(productUnitPrice,3)+'×'+fmt(quantity,0), fmt(productTotalPrice,2)+' 元'));\n  document.getElementById('r3_process').innerHTML = proc3.join('');\n\n  text('r3_productUnitPrice', fmt(productUnitPrice, 3));\n  text('r3_quantity', fmt(quantity, 0));\n  text('r3_productTotalPrice', fmt(productTotalPrice, 2));\n  text('r3_processingTotal',fmt(sumAfterTax,3));\n  return {A,B,G,H,sum:sumAfterTax,details,sheetUnitPrice,productUnitPrice,quantity,productTotalPrice};\n}\n\n// 骨架箱(上边条)输入框：手动修改即标记\"已填\"，切回自动只需清空\nfunction onSkeletonEdgeInput(){\n  const el = document.getElementById('s3_skeleton_edge');\n  if(!el) return;\n  const tag = document.getElementById('s3_skeleton_edge_tag');\n  if(el.value === '' || el.value === null){\n    el.removeAttribute('data-user-set');\n    if(tag){ tag.textContent = '≈2×(长+宽) 自动'; tag.className = 'auto-tag auto'; }\n  } else {\n    el.setAttribute('data-user-set','1');\n    if(tag){ tag.textContent = '手动'; tag.className = 'auto-tag manual'; }\n  }\n  calcAll();\n}\n\n// ==================== Custom Checkbox ====================\nlet customCBCounter = 0;\n\nfunction addCustomCheckbox(name, price, checked){\n  const id = 'custom_' + (++customCBCounter);\n  const _name = name || '自定义工序';\n  const _price = price || 0;\n  const _checked = checked || false;\n  renderCustomCB(id, _name, _price, _checked);\n  calcAll();\n}\n\nfunction renderCustomCB(id, name, price, checked){\n  const grid = document.getElementById('cb_custom_grid');\n  const item = document.createElement('div');\n  item.className = 'cb-item custom' + (checked ? ' checked' : '');\n  item.dataset.key = id;\n  item.innerHTML = `\n    <input type=\"checkbox\" ${checked?'checked':''} onchange=\"calcAll()\">\n    <input type=\"text\" class=\"cb-text-input\" value=\"${escapeHTML(name)}\" oninput=\"calcAll()\" placeholder=\"工序名称\">\n    <input type=\"number\" value=\"${Number(price) || 0}\" oninput=\"calcAll()\" style=\"width:50px;padding:2px 5px;border:1px solid var(--gray-300);border-radius:4px;font-size:11px;text-align:right;\">\n    <span style=\"font-size:10px;color:#9ca3af;\">元</span>\n    <span class=\"cb-del-btn\" onclick=\"removeCustomCheckbox('${id}')\">×</span>\n  `;\n  grid.appendChild(item);\n}\n\nfunction removeCustomCheckbox(id){\n  const item = document.querySelector('#cb_custom_grid .cb-item[data-key=\"'+id+'\"]');\n  if(item) item.remove();\n  calcAll();\n}\n\nfunction getCustomCBData(){\n  // 从 DOM 读取当前状态（保存模板时用）\n  const items = document.querySelectorAll('#cb_custom_grid .cb-item');\n  return Array.from(items).map(item=>{\n    const cb = item.querySelector('input[type=\"checkbox\"]');\n    const text = item.querySelector('.cb-text-input');\n    const price = item.querySelector('input[type=\"number\"]');\n    return {\n      id: item.dataset.key,\n      name: text ? text.value : '',\n      price: price ? +price.value || 0 : 0,\n      checked: cb ? cb.checked : false\n    };\n  });\n}\n\n// ==================== Step 4 ====================\nfunction calcStep4(r3 = calcStep3()) {\n  const A=document.getElementById('s1_tax').value, B=+val('s1_taxRate')/100,\n    C=+val('s1_quantity'),                     // 数量直接从产品参数取\n    D=r3.productUnitPrice,\n    E=document.getElementById('s1_shipFee').value==='是' ? +val('s4_shipping') : 0,  // 是否含运:否→运费不计入\n    F=+val('s4_die'), Fa=+val('s4_screen'),\n    G=+val('s4_fractionAdj')/100, H=+val('s4_priceAdj');\n\n  // 刀模费 + 丝网费 一起计入一次性分摊\n  const moldTotal = F + Fa;\n  const perUnitExtraVal = C > 0 ? (E+moldTotal)/C : 0;\n  const I=(A==='是')? D*(1+G)+(perUnitExtraVal+H)*(1+B) : D*(1+G)+perUnitExtraVal+H;\n  const J=C*I;\n\n  // 计算过程（cpLine 格式）\n  const proc4 = [];\n  // (运费+刀模费+丝网费)/数量\n  const extraCalc = fmt(E,2)+'+'+fmt(F,2)+'+'+fmt(Fa,2);\n  const perUnitValStr = fmt(perUnitExtraVal,3);  // 最终报价（单）中直接引用此结果\n  if(C !== 0){\n    proc4.push(cpLine('(运费+刀模费+丝网费)/数量', '('+extraCalc+')/数量',\n      '('+extraCalc+')÷'+fmt(C,0), perUnitValStr+' 元/个'));\n  } else {\n    proc4.push(cpLine('(运费+刀模费+丝网费)/数量', '', '', '0 元/个'));\n  }\n  // 最终报价（单）\n  const finalUnitFormula = (A==='是')\n    ? '成品价格(单)×(1+零头修正%)+((运费+刀模费+丝网费)/数量+价格修正)×(1+税率%)'\n    : '成品价格(单)×(1+零头修正%)+(运费+刀模费+丝网费)/数量+价格修正';\n  const finalUnitCalc = (A==='是')\n    ? fmt(D,2)+'×(1+'+fmt(G*100,0)+'%)+('+perUnitValStr+'+'+fmt(H,2)+')×(1+'+fmt(B*100,0)+'%)'\n    : fmt(D,2)+'×(1+'+fmt(G*100,0)+'%)+'+perUnitValStr+'+'+fmt(H,2);\n  proc4.push(cpLine('最终报价（单）', finalUnitFormula, finalUnitCalc, fmt(I,3)+' 元/个'));\n  // 最终报价（总）\n  proc4.push(cpLine('最终报价（总）', '最终报价(单)×数量',\n    fmt(I,3)+'×'+fmt(C,0), fmt(J,2)+' 元'));\n  document.getElementById('r4_process').innerHTML = proc4.join('');\n\n  text('r4_perUnitExtra',fmt(perUnitExtraVal,3));\n  text('r4_finalUnitPrice',fmt(I,3));\n  text('r4_quantity',fmt(C,0));\n  // 最终报价（总）保留2位小数\n  text('r4_finalTotalPrice',fmt(J,2));\n\n  return {A,B,C,D,E,F,Fa,G,H,I,J};\n}\n\n// ==================== Summary ====================\nfunction updateSummary(r1,r2,r3,r4){\n  text('sum_taxStatus', document.getElementById('s1_tax').value);\n  // 未选样式 / 箱类未选 dimType：右侧汇总也清空，避免显示 0.00 误导\n  const _needDim = BOX_STYLES.includes(state.style);\n  const _noData = !state.style || (_needDim && !state.dimType);\n  if(_noData){\n    text('sum_finalUnit','—');\n    text('sum_finalTotal','—');\n    text('sum_quantity','—');\n    text('sum_volume','—');\n    text('sum_tons','—');\n    return;\n  }\n  text('sum_finalUnit', fmt(r4.I,3)+' 元');\n  text('sum_finalTotal', fmt(r4.J,2)+' 元');\n  text('sum_quantity', fmt(r1.H,0));\n  text('sum_volume', fmt(r1.M,2)+' m³');\n  text('sum_tons', fmt(r1.N,2)+' T');\n  // 注：汇总区没有\"利润率\"卡片（对应元素 sum_profitRate 在 HTML 中不存在，\n  // 板材利润率显示在原料区的 r2_profitRate）。此处不再写不存在的元素。\n}\n\n// ==================== Utils ====================\n// ⚠️ 这两个工具必须容错：页面里任何一处\"引用了不存在的 id\"，都会让整条调用链在末尾抛\n// TypeError 中断。历史事故：updateSummary 写 sum_profitRate（该元素在 HTML 中并不存在），\n// 使 calcAll() 每次都在最后一行抛错，导致「点击立即同步」的横幅因异常而无法被移除。\n// 故这里对 null 做安全兜底（与 setVal() 的写法保持一致）。\nfunction val(id){ const el=document.getElementById(id); if(!el) return 0; return parseFloat(el.value)||0; }\nfunction text(id,t){ const el=document.getElementById(id); if(el) el.textContent=t; }\nfunction fmt(v,d){ if(v===undefined||v===null||isNaN(v)) return d===0?'0':'0'; const f=Math.pow(10,d); return(Math.round(v*f)/f).toFixed(d); }\nfunction escapeHTML(value){\n  return String(value ?? '').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]));\n}\n// 计算过程展示辅助：k=参数名，expr=公式(带数值)，val=结果(带单位)\n// 计算过程展示：k=体量名称 / formula=计算公式(符号) / calc=计算过程(纯数字+单位) / val=结果(带单位)\nfunction cpLine(k, formula, calc, val){\n  const formulaPart = formula ? `<span class=\"cp-sep\">=</span><span class=\"cp-expr\">${escapeHTML(formula)}</span>` : '';\n  return `<div class=\"cp-line\"><span class=\"cp-k\">${escapeHTML(k)}</span>${formulaPart}<span class=\"cp-sep\">=</span><span class=\"cp-calc\">${escapeHTML(calc)}</span><span class=\"cp-sep\">=</span><span class=\"cp-v\">${escapeHTML(val)}</span></div>`;\n}\nfunction cpHead(t){ return `<div class=\"cp-head\">${t}</div>`; }\n\nconst defaults = {};\nconst TEMPLATE_VERSION = 166;\n// 可接受的最低模板版本：v165→v166 将工序\"纤维胶/魔术贴角(4角)\"拆分为\"纤维胶\"+\"魔术贴角(4角)\"\n// 两个独立勾选项（s3p_fibertape → s3p_fiber + s3p_velcro_corner）。\n// checkbox 状态按 DOM 索引序列化，新增勾选框使旧模板索引错位，故 MIN 同步升至 166，旧模板失效。\n// ⚠️ 只有 DOM/字段结构变化（增删输入框/勾选框/id 改名）才允许 bump 版本号——\n// 纯 JS 逻辑修复不要 bump，否则用户已存模板会被误判失效！\nconst TEMPLATE_MIN_VERSION = 166;\n\n// ============ 共享模板（云端同步）============\n// 已发布为 WorkBuddy 分享链接；共享模板由本站自带轻量后端托管：\n//   GET  /shared-template.json  → 所有人读取（自动同步，匿名公开读）\n//   POST /api/template          → 仅管理员写入（需管理员密码，服务端落盘 JSON）\n// 不再依赖 GitHub Pages / 云存储。模板存为服务端文件，任何打开链接的人都能拉取，\n// 管理员一键写入、秒级生效。\nconst SHARED_TEMPLATE_URL = '/shared-template.json';   // 站点自身后端接口（同源）\nlet sharedTemplate = null;   // 运行时从后端载入（admin 发布的全局模板）\nlet _appliedPublishedAt = null;  // 当前页面已应用的共享模板发布时间戳\nconst SYNC_BANNER_ID = 'bh-sync-banner';   // \"有新模板\"提示横幅（用 DOM 是否存在作为唯一状态源，避免标志位卡死）\n\n// 异步拉取共享模板（全员同步读取）。失败/为空则回退 localStorage/出厂。\n// 带 ?_t= 时间戳参数做缓存穿透，确保同事立刻拿到最新模板。\nasync function loadSharedTemplate(){\n  try {\n    const res = await fetch(SHARED_TEMPLATE_URL + '?_t=' + Date.now(), { cache: 'no-store', signal: AbortSignal.timeout(8000) });\n    if(!res.ok) return;\n    const data = await res.json();\n    if(data && !data._empty && data._v >= TEMPLATE_MIN_VERSION && data._v <= TEMPLATE_VERSION){\n      sharedTemplate = data;\n    }\n  } catch(e) { /* 离线或网络失败：忽略，回退本地 */ }\n}\n\n// admin 存为模板时，写入本站后端（服务端落盘 JSON，全员刷新即同步，秒级生效）\nasync function publishSharedTemplate(flat){\n  const role = sessionStorage.getItem('role');\n  const pwd  = sessionStorage.getItem('bh_pwd') || '';\n  if(role !== 'admin'){\n    showToast('需管理员登录后才能发布共享模板');\n    return;\n  }\n  const payload = Object.assign({}, flat, { _publishedAt: new Date().toISOString() });\n  try {\n    const up = await fetch('/api/template', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ password: pwd, template: payload })\n    });\n    if(up.ok){\n      sharedTemplate = payload;            // 当前页面立即生效\n      _appliedPublishedAt = payload._publishedAt;\n      showToast('✓ 已发布到云端，所有人刷新即同步');\n      waitForSharedTemplateLive(payload._publishedAt);   // 轮询确认真正上线后再提示\n    } else if(up.status === 403){\n      showToast('发布失败：管理员密码校验未通过');\n    } else {\n      const err = await up.json().catch(()=>({}));\n      showToast('发布失败：' + (err.message || ('HTTP ' + up.status)));\n    }\n  } catch(e){\n    showToast('发布失败：网络错误');\n  }\n}\n\n// 发布后轮询线上 shared-template.json，确认已能提供新版本再提示 admin\nasync function waitForSharedTemplateLive(ts){\n  const deadline = Date.now() + 150000;   // 最多等 2.5 分钟\n  while(Date.now() < deadline){\n    await new Promise(r=>setTimeout(r, 6000));\n    try {\n      const res = await fetch(SHARED_TEMPLATE_URL + '?_t=' + Date.now(), { cache: 'no-store' });\n      if(res.ok){\n        const d = await res.json();\n        if(d && d._publishedAt === ts){ showToast('✓ 共享模板已上线，所有人刷新即同步'); return; }\n      }\n    } catch(e) {}\n  }\n  showToast('已提交，部署稍慢——同事约1~2分钟后刷新即可同步');\n}\n\n// 同事端：标签页切回前台时检测是否有更新的共享模板（不自动覆盖，避免打断正在填的报价）\nasync function checkSharedTemplateUpdate(){\n  try {\n    const res = await fetch(SHARED_TEMPLATE_URL + '?_t=' + Date.now(), { cache: 'no-store' });\n    if(!res.ok) return;\n    const data = await res.json();\n    if(!data || data._empty) return;\n    if(!(data._v >= TEMPLATE_MIN_VERSION && data._v <= TEMPLATE_VERSION)) return;\n    if(!data._publishedAt || data._publishedAt === _appliedPublishedAt) return;\n    showSyncBanner(data);\n  } catch(e) {}\n}\n\n// 顶部横幅：检测到新模板时提示，点\"立即同步\"一键应用（动态创建、无表单元素，不影响模板快照）\n// 状态以「页面上是否存在该元素」为准，不再用布尔标志位（标志位一旦与 DOM 不同步就会卡死）。\nfunction removeSyncBanner(){\n  const el = document.getElementById(SYNC_BANNER_ID);\n  if(el) el.remove();\n}\nfunction showSyncBanner(data){\n  removeSyncBanner();   // 更新为最近一次检测到的模板。\n  const bar = document.createElement('div');\n  bar.id = SYNC_BANNER_ID;\n  bar.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:10000;background:#2563eb;color:#fff;padding:10px 16px;display:flex;justify-content:center;align-items:center;gap:14px;font-size:14px;box-shadow:0 2px 8px rgba(0,0,0,.25);';\n  const time = data._publishedAt ? new Date(data._publishedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) : '';\n  const label = document.createElement('span');\n  label.textContent = '📢 管理员发布了新模板' + (time ? '（' + time + '）' : '');\n  const btn = document.createElement('button');\n  btn.textContent = '立即同步';\n  btn.style.cssText = 'background:#fff;color:#2563eb;border:none;padding:4px 14px;border-radius:6px;cursor:pointer;font-size:14px;font-weight:600;';\n  btn.onclick = ()=>{\n    // 关键：先移除横幅，再应用数据。此前 bar.remove() 写在最后，\n    // 只要 captureDefaults()/calcAll() 中途抛一次异常，横幅就会永远卡在页面上。\n    removeSyncBanner();\n    try {\n      sharedTemplate = data;\n      _appliedPublishedAt = data._publishedAt;\n      captureDefaults();   // 内部会 applyDefaults 把新模板填到页面\n      calcAll();\n      showToast('✓ 已同步最新共享模板');\n    } catch(e){\n      console.error('[同步共享模板] 失败：', e);\n      showToast('同步时出错：' + ((e && e.message) || e), 'warn');\n    }\n  };\n  const close = document.createElement('button');\n  close.textContent = '稍后';\n  close.style.cssText = 'background:transparent;color:#fff;border:1px solid rgba(255,255,255,.6);padding:4px 12px;border-radius:6px;cursor:pointer;font-size:13px;';\n  close.onclick = ()=>{ removeSyncBanner(); };\n  bar.appendChild(label); bar.appendChild(btn); bar.appendChild(close);\n  document.body.appendChild(bar);\n}\n\n// HTML 出厂初始值快照（页面加载、用户未修改前抓取，供\"重置\"使用）\nconst htmlDefaults = {};\nfunction captureDefaults(){\n  // 首次调用（页面加载时）快照 HTML 出厂初始值——此时 DOM 尚未被用户修改\n  if(Object.keys(htmlDefaults).length === 0){\n    document.querySelectorAll('input[type=\"number\"], input[type=\"text\"], select').forEach(el=>{\n      htmlDefaults[el.id] = el.value;\n    });\n    document.querySelectorAll('input[type=\"checkbox\"]').forEach((el, idx)=>{\n      htmlDefaults['cb_'+idx] = el.checked;\n    });\n    htmlDefaults.style = state.style;\n    htmlDefaults.dimType = state.dimType;\n    htmlDefaults.materialType = state.materialType;\n  }\n  // 优先采用 admin 发布的共享模板（全员同步）；其次本地 localStorage；再次出厂快照\n  let saved = null;\n  if(sharedTemplate && sharedTemplate._v >= TEMPLATE_MIN_VERSION && sharedTemplate._v <= TEMPLATE_VERSION){\n    saved = sharedTemplate;\n    _appliedPublishedAt = sharedTemplate._publishedAt || null;\n  } else {\n    try { saved = JSON.parse(localStorage.getItem('bh_quote_template')); } catch(e) {}\n  }\n  // 加载所有配方的自定义价格\n  try { Object.assign(materialPrices, JSON.parse(localStorage.getItem('bh_material_prices')) || {}); } catch(e) {}\n  if(saved && saved._v >= TEMPLATE_MIN_VERSION && saved._v <= TEMPLATE_VERSION){\n    Object.assign(defaults, saved);\n    // 模板若包含全部原料配方的子属性（materialPrices），合并进运行时，\n    // 使加载模板后切到任意配方都还原其价格与比例\n    if(saved.materialPrices && typeof saved.materialPrices === 'object'){\n      Object.assign(materialPrices, saved.materialPrices);\n    }\n    // 模板中若有配方自定义价格和比例，也同步到 materialPrices（刷新后切换配方仍有效）\n    if(saved.materialType && saved._userSetPrices){\n      materialPrices[saved.materialType] = {\n        newPrice:    parseFloat(saved.s2_newPrice)    || 0,\n        masterPrice: parseFloat(saved.s2_masterPrice) || 0,\n        specialPrice:parseFloat(saved.s2_specialPrice)|| 0,\n        fixedCost:   parseFloat(saved.s2_fixedCost)   || 0,\n        masterRatio: parseFloat(saved.s2_masterRatio) || 0,\n        specialRatio:parseFloat(saved.s2_specialRatio)|| 0,\n        _userSet: Array.isArray(saved._userSetPrices) ? saved._userSetPrices : []\n      };\n    }\n    applyDefaults();\n  } else {\n    // 版本不匹配或首次：用 HTML 出厂快照（不依赖实时 DOM，避免抓到用户输入值）\n    Object.assign(defaults, htmlDefaults);\n  }\n}\n\n// 把 defaults 应用到页面（恢复 UI 状态）\nfunction applyDefaults(){\n  document.querySelectorAll('input[type=\"number\"], input[type=\"text\"], select').forEach(el=>{\n    if(defaults[el.id] !== undefined) el.value = defaults[el.id];\n  });\n  document.querySelectorAll('input[type=\"checkbox\"]').forEach((el, idx)=>{\n    if(defaults['cb_'+idx] !== undefined) el.checked = defaults['cb_'+idx];\n  });\n  // 恢复\"用户已填\"的价格标记（让用户保存的价格不被类型切换覆盖）\n  const userSetList = Array.isArray(defaults._userSetPrices) ? defaults._userSetPrices : [];\n  const allPriceIds = ['s2_newPrice','s2_masterPrice','s2_specialPrice','s2_fixedCost'];\n  allPriceIds.forEach(id => {\n    const el = document.getElementById(id);\n    if(!el) return;\n    if(userSetList.indexOf(id) >= 0) el.setAttribute('data-user-set', '1');\n    else el.removeAttribute('data-user-set');\n  });\n  // 后加工：重置时回归默认单价（清除手动覆盖标记），骨架箱上边条回到\"2×(长+宽)自动\"\n  document.querySelectorAll('.cb-item input[type=\"number\"]').forEach(inp=>{\n    if(userSetList.includes(inp.id)) inp.setAttribute('data-user-set', '1');\n    else inp.removeAttribute('data-user-set');\n  });\n  const seTag = document.getElementById('s3_skeleton_edge_tag');\n  if(seTag){\n    const manualEdge = userSetList.includes('s3_skeleton_edge');\n    seTag.textContent = manualEdge ? '手动' : '≈2×(长+宽) 自动';\n    seTag.className = manualEdge ? 'auto-tag manual' : 'auto-tag auto';\n  }\n  // 样式选择（大类/具体箱型统一由 syncStyleUI 联动）\n  state.style = defaults.style;\n  state.boxCat = BOX_STYLES.includes(defaults.style);\n  state.caseCat = defaults.style === '投票箱';\n  if(state.caseCat){\n    state.lastCaseStyle = defaults.style;\n    state.caseDimType = defaults.dimType === '外尺' ? '外尺' : '';\n  }\n  if(state.boxCat && !state.caseCat){\n    state.lastBoxStyle = defaults.style;\n    state.boxDimType = ['外尺','内尺'].includes(defaults.dimType) ? defaults.dimType : '';\n  }\n  syncStyleUI();\n  document.querySelectorAll('#s1_dimtype_row .type-chip').forEach(c=>c.classList.remove('active'));\n  const dimChip = document.querySelector('#s1_dimtype_row .type-chip[data-dim=\"'+defaults.dimType+'\"]');\n  if(dimChip) dimChip.classList.add('active');\n  state.dimType = defaults.dimType;\n  syncStyleUI();\n  // 材料类型\n  document.querySelectorAll('#s2_type_row .type-chip').forEach(c=>c.classList.remove('active'));\n  const matChip = document.querySelector('#s2_type_row .type-chip[data-type=\"'+defaults.materialType+'\"]');\n  if(matChip) matChip.classList.add('active');\n  state.materialType = defaults.materialType;\n\n  // 恢复配方价格和比例：优先从 materialPrices 读取，没有则从 defaults（模板）读取\n  const mt = defaults.materialType;\n  const savedPrices = materialPrices[mt];\n  const d = materialDefaults[mt];\n  if(savedPrices){\n    // 有 materialPrices 记录：用用户自定义价格和比例\n    const priceMap = [\n      ['s2_newPrice',    savedPrices.newPrice],\n      ['s2_masterPrice', savedPrices.masterPrice],\n      ['s2_specialPrice',savedPrices.specialPrice],\n      ['s2_fixedCost',   savedPrices.fixedCost]\n    ];\n    priceMap.forEach(([id, val]) => {\n      const f = document.getElementById(id);\n      if(!f || val === undefined || val === null) return;\n      f.value = val;\n      if(savedPrices._userSet && savedPrices._userSet.indexOf(id) >= 0){\n        f.setAttribute('data-user-set', '1');\n      } else {\n        f.removeAttribute('data-user-set');\n      }\n    });\n    // 比例也恢复\n    if(savedPrices.masterRatio !== undefined) document.getElementById('s2_masterRatio').value = savedPrices.masterRatio;\n    if(savedPrices.specialRatio !== undefined) document.getElementById('s2_specialRatio').value = savedPrices.specialRatio;\n  } else if(d){\n    // 没有 materialPrices 记录：用 materialDefaults 默认值\n    const priceMap = [\n      ['s2_newPrice',    d.newPrice],\n      ['s2_masterPrice', d.masterPrice],\n      ['s2_specialPrice',d.specialPrice],\n      ['s2_fixedCost',   d.fixedCost]\n    ];\n    priceMap.forEach(([id, val]) => {\n      const f = document.getElementById(id);\n      if(!f || val === undefined || val === null) return;\n      f.value = val;\n      f.removeAttribute('data-user-set');\n    });\n    document.getElementById('s2_masterRatio').value = d.masterRatio;\n    document.getElementById('s2_specialRatio').value = d.specialRatio;\n  }\n  // 恢复自定义勾选框\n  const customGrid = document.getElementById('cb_custom_grid');\n  if(customGrid) customGrid.innerHTML = '';\n  customCBCounter = 0;\n  if(Array.isArray(defaults._customCB)){\n    defaults._customCB.forEach(c=>{\n      customCBCounter++;\n      const id = 'custom_' + customCBCounter;\n      renderCustomCB(id, c.name, c.price, c.checked);\n    });\n  }\n}\n\n// 是否存在版本有效的已存模板\nfunction hasSavedTemplate(){\n  if(sharedTemplate && sharedTemplate._v >= TEMPLATE_MIN_VERSION && sharedTemplate._v <= TEMPLATE_VERSION) return true;\n  try {\n    const s = JSON.parse(localStorage.getItem('bh_quote_template'));\n    return !!(s && s._v >= TEMPLATE_MIN_VERSION && s._v <= TEMPLATE_VERSION);\n  } catch(e) { return false; }\n}\n\nfunction resetAll(){\n  // 关键①：绝不删除 localStorage —— 已存模板必须保留（重置 ≠ 删除模板）！\n  // 关键②：绝不从当前 DOM 抓取默认值（当前 DOM 是用户输入值，抓了等于没重置）。\n  // 做法：清空内存状态，完全模拟一次\"全新页面加载\"——\n  // captureDefaults 自动判断：有已存模板→恢复到模板；没有→恢复到出厂快照 htmlDefaults\n  Object.keys(defaults).forEach(k => delete defaults[k]);\n  Object.keys(materialPrices).forEach(k => delete materialPrices[k]);\n  state.lastBoxStyle = '';\n  state.lastCaseStyle = '';\n  state.caseDimType = '';\n  state.boxDimType = '';\n  captureDefaults();\n  applyDefaults();\n  // 清空智能识别框和提示\n  const parseInput = document.getElementById('parseInput');\n  if(parseInput) parseInput.value = '';\n  const parseResult = document.getElementById('parseResult');\n  if(parseResult) parseResult.innerHTML = '';\n  calcAll();\n  showToast(hasSavedTemplate() ? '已重置为已保存的模板' : '已重置为出厂默认值');\n}\n\nfunction showToast(msg, type){\n  let t = document.getElementById('toast');\n  if(!t){\n    t = document.createElement('div');\n    t.id = 'toast';\n    t.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:#16a34a;color:white;padding:10px 24px;border-radius:8px;font-size:14px;z-index:9999;box-shadow:0 2px 8px rgba(0,0,0,0.2);opacity:0;transition:opacity 0.3s;';\n    document.body.appendChild(t);\n  }\n  t.style.background = (type === 'warn') ? '#dc2626' : '#16a34a';\n  t.textContent = msg;\n  t.style.opacity = '1';\n  clearTimeout(t._timer);\n  t._timer = setTimeout(()=>{ t.style.opacity = '0'; }, type === 'warn' ? 3000 : 2000);\n}\n\n// ==================== Parse & Auto-Fill ====================\nfunction parseAndFill() {\n  const raw = document.getElementById('parseInput').value.trim();\n  if(!raw) { showParseResult([], '请输入内容'); return; }\n\n  // 统一文本：中文标点→空格，全角→半角，压缩空格\n  let t = raw\n    .replace(/[，,、；;\\n\\r\\t]/g, ' ')\n    .replace(/[：:]/g, ':')\n    .replace(/[（）()]/g, ' ')\n    .replace(/\\s+/g, ' ');\n  let filled = [];\n  let work = ' ' + t + ' '; // 工作副本，匹配后移除已消费部分\n  const done = new Set();   // 记录已填写的字段类型\n\n  // 工具函数：正则匹配并从 work 中移除\n  function take(re) {\n    const m = work.match(re);\n    if(m) { work = work.replace(m[0], ' '); return m; }\n    return null;\n  }\n  // 工具函数：纯字符串匹配并移除\n  function takeStr(s) {\n    const idx = work.indexOf(s);\n    if(idx >= 0) { work = work.substring(0, idx) + ' ' + work.substring(idx + s.length); return true; }\n    return false;\n  }\n  function has(s) { return work.indexOf(s) >= 0; }\n\n  // === 1. 尺寸（最先匹配，避免数字被其他规则吞掉）===\n  // 3 维: 300×200×100 → 长×宽×高\n  let dm = take(/(\\d+(?:\\.\\d+)?)\\s*[×xX\\*]\\s*(\\d+(?:\\.\\d+)?)\\s*[×xX\\*]\\s*(\\d+(?:\\.\\d+)?)/);\n  if(dm) {\n    setVal('s1_length', dm[1]); setVal('s1_width', dm[2]); setVal('s1_height', dm[3]);\n    filled.push('尺寸:'+dm[1]+'×'+dm[2]+'×'+dm[3]);\n  } else {\n    // 2 维: 300×200 → 长×宽\n    let dm2 = take(/(\\d+(?:\\.\\d+)?)\\s*[×xX\\*]\\s*(\\d+(?:\\.\\d+)?)/);\n    if(dm2) {\n      setVal('s1_length', dm2[1]); setVal('s1_width', dm2[2]);\n      filled.push('尺寸:'+dm2[1]+'×'+dm2[2]+'(长×宽)');\n    } else {\n      // 关键词: 长300 宽200 高100\n      let m = take(/(?:长|外直径)\\s*:?\\s*(\\d+(?:\\.\\d+)?)/);\n      if(m) { setVal('s1_length', m[1]); filled.push('长:'+m[1]); }\n      m = take(/(?:宽|内直径)\\s*:?\\s*(\\d+(?:\\.\\d+)?)/);\n      if(m) { setVal('s1_width', m[1]); filled.push('宽:'+m[1]); }\n      m = take(/高\\s*:?\\s*(\\d+(?:\\.\\d+)?)/);\n      if(m) { setVal('s1_height', m[1]); filled.push('高:'+m[1]); }\n    }\n  }\n\n  // === 3. 产品样式（支持简写，长词优先）===\n  const styleMap = [\n    ['投票箱', '投票箱'],\n    ['纸箱式', '纸箱式'], ['纸箱', '纸箱式'], ['纸板', '纸箱式'],\n    ['插底式', '插底式'], ['插底', '插底式'],\n    ['焊底式', '焊底式'], ['焊底', '焊底式'],\n    ['骨架箱', '骨架箱'], ['骨架', '骨架箱'], ['骨架式', '骨架箱'],\n    ['全包式', '全包式'], ['全包', '全包式'],\n    ['四拼式', '四拼式'], ['四拼', '四拼式'],\n    ['圆盘', '圆盘'], ['圆盘式', '圆盘'],\n    ['板材', '板材'], ['板式', '板材'],\n    ['圆', '圆盘'],\n    ['板', '板材'],\n  ];\n  for(let [key, val] of styleMap) {\n    if(!has(key)) continue;\n    // 骨架箱：排除\"骨架箱顶角\"\"骨架箱边条\"\n    if((key === '骨架箱' || key === '骨架') && work.match(/骨架箱?[顶边条角]/)) continue;\n    // 圆：避免匹配\"圆盘\"（已检查）或数字后跟\"圆\"（货币）\n    if(key === '圆' && (has('圆盘') || work.match(/\\d圆/))) continue;\n    // 板：避免匹配\"板材\"（已检查）\n    if(key === '板' && has('板材')) continue;\n    takeStr(key);\n    clickStyle(val);\n    filled.push('样式:'+val);\n    break;\n  }\n\n  // === 4. 尺寸类型（支持简写\"内\"\"外\"）===\n  if(has('内尺')) { takeStr('内尺'); clickDimType('内尺'); filled.push('内尺'); }\n  else if(has('外尺')) { takeStr('外尺'); clickDimType('外尺'); filled.push('外尺'); }\n  else if(work.match(/\\s内(?![尺径])/)) { take(/内(?![尺径])/); clickDimType('内尺'); filled.push('内尺'); }\n  else if(work.match(/\\s外(?![尺径])/)) { take(/外(?![尺径])/); clickDimType('外尺'); filled.push('外尺'); }\n\n  // === 5. 材料类型（长词优先，支持简写）===\n  if(take(/新料?\\+?透明母料|透明母料|透明/)) { clickMatType('新料+透明母料'); filled.push('材料:新料+透明母料'); }\n  else if(take(/回料?\\+?母料|回料母料|回料/)) { clickMatType('回料+母料'); filled.push('材料:回料+母料'); }\n  else if(takeStr('防静电')) { clickMatType('防静电'); filled.push('材料:防静电'); }\n  else if(takeStr('导电')) { clickMatType('导电'); filled.push('材料:导电'); }\n  else if(take(/耐低温|耐寒/)) { clickMatType('耐低温'); filled.push('材料:耐低温'); }\n  else if(takeStr('阻燃')) { clickMatType('阻燃'); filled.push('材料:阻燃'); }\n  else if(take(/普通(?!钉)/)) { clickMatType('普通'); filled.push('材料:普通'); }\n\n  // === 6. 厚度（正序\"厚3\" + 反序\"3厚\" + \"3mm\" + \"板厚3\"）===\n  m = take(/(?<!\\d)(?:板厚|厚度|厚)\\s*[:：=]?\\s*(\\d+(?:\\.\\d+)?)\\s*(?:mm|MM|毫米)?/);\n  if(!m) m = take(/(\\d+(?:\\.\\d+)?)\\s*(?:mm|MM|毫米)(?=\\s|$)/);\n  if(!m) m = take(/(\\d+(?:\\.\\d+)?)\\s*厚/);\n  if(m) { setVal('s1_thickness', m[1]); filled.push('厚度:'+m[1]); done.add('thickness'); }\n\n  // === 7. 克重（正序\"克重600\" + 反序\"600克\" + \"克600\" + \"基重600\" + \"600gsm\"）===\n  m = take(/(?:克重|基重)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)/);\n  if(!m) m = take(/(\\d+(?:\\.\\d+)?)\\s*(?:g\\/㎡|g\\/m2|gsm|GSM|g)(?!材)/);\n  if(!m) m = take(/(?<!\\d)克\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)/);\n  if(m) { setVal('s1_weight', m[1]); filled.push('克重:'+m[1]); done.add('weight'); }\n\n  // === 8. 数量（支持 个/件/只/pcs 与 量:1000 / 数量:1000）===\n  m = take(/(?:数量|总数)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)/);\n  if(!m) m = take(/量\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)/);\n  if(!m) m = take(/(\\d+(?:\\.\\d+)?)\\s*(?:个|件|只|pcs|PCS|片)/);\n  if(m) { setVal('s1_quantity', m[1]); filled.push('数量:'+m[1]); done.add('quantity'); }\n\n  // === 9. 含税+税点（复合\"含税7%\"优先，再独立税点）===\n  m = take(/含税\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) {\n    setSelect('s1_tax', '是');\n    setVal('s1_taxRate', m[1]);\n    filled.push('含税 税点:'+m[1]+'%');\n  } else if(take(/不含税|无税/)) {\n    setSelect('s1_tax', '否');\n    filled.push('不含税');\n  } else if(takeStr('含税')) {\n    setSelect('s1_tax', '是');\n    filled.push('含税');\n  }\n  // 独立税点（\"税7\"\"税点7\"）\n  m = take(/(?:税点|税率|税)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) { setVal('s1_taxRate', m[1]); filled.push('税点:'+m[1]+'%'); }\n\n  // === 10. 母料比例（支持\"母33\"\"母料33\"）===\n  m = take(/(?:母料比例|母料|母)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) { setVal('s2_masterRatio', m[1]); filled.push('母料:'+m[1]+'%'); done.add('masterRatio'); }\n\n  // === 11. 特殊料比例（支持\"特50\"\"特殊料50\"）===\n  m = take(/(?:特殊料比例|特殊料|特殊|特)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) { setVal('s2_specialRatio', m[1]); filled.push('特殊料:'+m[1]+'%'); done.add('specialRatio'); }\n\n  // === 11.5 % 符号兜底：未带关键词的裸 % 数字 → 母料比例 ===\n  if(!done.has('masterRatio')) {\n    let pm = take(/(\\d+(?:\\.\\d+)?)\\s*%/);\n    if(pm) { setVal('s2_masterRatio', pm[1]); filled.push('母料:'+pm[1]+'%(%)'); done.add('masterRatio'); }\n  }\n\n  // === 12. 新料价格 ===\n  m = take(/(?:新料价格|新料)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s2_newPrice', m[1]); filled.push('新料:'+m[1]); }\n\n  // === 13. 母料价格 ===\n  m = take(/母料价格\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s2_masterPrice', m[1]); filled.push('母料价:'+m[1]); }\n\n  // === 14. 特殊料价格 ===\n  m = take(/特殊料价格\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s2_specialPrice', m[1]); filled.push('特殊料价:'+m[1]); }\n\n  // === 15. 固定成本（支持\"固定1700\"）===\n  m = take(/(?:固定成本|固定)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s2_fixedCost', m[1]); filled.push('固定成本:'+m[1]); }\n\n  // === 16. 原料利润（支持\"利1800\"）===\n  m = take(/(?:原料利润|利润|利)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s2_profit', m[1]); filled.push('利润:'+m[1]); }\n\n  // === 17. 使用率 ===\n  m = take(/(?:使用率)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) { setVal('s1_usageRate', m[1]); filled.push('使用率:'+m[1]+'%'); }\n\n  // === 18. 加工工序（支持简写，铆钉先于打钉避免\"钉\"冲突）===\n  // 纤维胶（独立工序；先匹配，避免与\"魔术贴\"冲突）\n  m = take(/(?:纤维胶|胶)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('fiber', m[1]); filled.push('纤维胶:'+m[1]+'元'); }\n  else if(take(/(?:纤维胶|胶)/)) { checkProcess('fiber'); filled.push('纤维胶(默认)'); }\n\n  // 魔术贴角(4角)（独立工序；必须先于\"魔术贴\"匹配）\n  m = take(/魔术贴角\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('velcro_corner', m[1]); filled.push('魔术贴角:'+m[1]+'元'); }\n  else if(take(/魔术贴角/)) { checkProcess('velcro_corner'); filled.push('魔术贴角(默认)'); }\n\n  // 铆钉（先于打钉，避免\"钉\"匹配铆钉中的\"钉\"）\n  m = take(/(?:铆钉|铆)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('rivet', m[1]); filled.push('铆钉:'+m[1]+'元'); }\n  else if(take(/(?:铆钉|铆)/)) { checkProcess('rivet'); filled.push('铆钉(默认)'); }\n\n  // 打钉/钉子/钉\n  m = take(/(?:普通钉|打钉|钉子|钉)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('nail', m[1]); filled.push('打钉:'+m[1]+'元'); }\n  else if(take(/(?:普通钉|打钉|钉子|钉)/)) { checkProcess('nail'); filled.push('打钉(默认)'); }\n\n  // 丝印（印刷工艺）—— 严格匹配，必须包含\"印\"字，避免与\"丝网\"混淆\n  m = take(/(?:丝印费|丝印)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('silkprint', m[1]); filled.push('丝印:'+m[1]+'元'); }\n  else if(take(/(?:丝印费|丝印)/)) { checkProcess('silkprint'); filled.push('丝印(默认)'); }\n\n  // 把手\n  m = take(/(?:把手费|手把|把手)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('handle', m[1]); filled.push('把手:'+m[1]+'元'); }\n  else if(take(/(?:把手费|手把|把手)/)) { checkProcess('handle'); filled.push('把手(默认)'); }\n\n  // 魔术贴/贴（后面不跟\"角\"）\n  m = take(/魔术贴(?!角)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('velcro', m[1]); filled.push('魔术贴:'+m[1]+'元'); }\n  else if(take(/魔术贴(?!角)/)) { checkProcess('velcro'); filled.push('魔术贴(默认)'); }\n  else { m = take(/贴(?!角)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/); if(m) { checkProcess('velcro', m[1]); filled.push('魔术贴:'+m[1]+'元'); } else if(take(/贴(?!角)/)) { checkProcess('velcro'); filled.push('魔术贴(默认)'); } }\n\n  // 骨架箱顶角/顶角/角\n  m = take(/(?:骨架箱顶角|骨架箱角|顶角|角)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('skeleton_corner', m[1]); filled.push('骨架箱角:'+m[1]+'元'); }\n  else if(take(/(?:骨架箱顶角|骨架箱角|顶角|角)/)) { checkProcess('skeleton_corner'); filled.push('骨架箱角(默认)'); }\n\n  // 骨架箱边条/边条/边\n  m = take(/(?:骨架箱边条|上边条|边条|边)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('skeleton_edge', m[1]); filled.push('边条:'+m[1]+'元'); }\n  else if(take(/(?:骨架箱边条|上边条|边条|边)/)) { checkProcess('skeleton_edge'); filled.push('边条(默认)'); }\n\n  // 卡夹/夹\n  m = take(/(?:卡夹|夹)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('clip', m[1]); filled.push('卡夹:'+m[1]+'元'); }\n  else if(take(/(?:卡夹|夹)/)) { checkProcess('clip'); filled.push('卡夹(默认)'); }\n\n  // 人工\n  m = take(/(?:人工费|人工)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { checkProcess('labor', m[1]); filled.push('人工:'+m[1]+'元'); }\n  else if(take(/(?:人工费|人工)/)) { checkProcess('labor'); filled.push('人工(默认)'); }\n\n  // === 19. 附加费用计算（支持简写）===\n  m = take(/(?:运费|运)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s4_shipping', m[1]); filled.push('运费:'+m[1]); }\n\n  // 刀模费 / 丝网费 —— 严格匹配，分别落到两个字段\n  // 1) 刀模（模版/刀版/刀线）\n  m = take(/(?:刀模费|刀版费|模版费|刀模|刀版|模版|刀线|刀)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s4_die', m[1]); filled.push('刀模费:'+m[1]); }\n\n  // 2) 丝网 —— 必须带\"网\"字（不含\"印\"字），避免与\"丝印\"（印刷工艺）混淆\n  m = take(/(?:丝网费|丝网)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s4_screen', m[1]); filled.push('丝网费:'+m[1]); }\n\n  // 3) 兼容旧写法\"刀+丝X\" / \"刀丝X\" / \"刀模丝网X\"——按逗号或空格拆分，分别填到两个字段\n  //    仅当上面两条都未填时启用（避免重复覆盖用户已显式填好的值）\n  if(!val('s4_die') && !val('s4_screen')) {\n    m = take(/(?:刀模丝网|刀\\+丝|刀丝)\\s*[:：]?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n    if(m) {\n      const total = +m[1];\n      // 经验默认值：刀模费 : 丝网费 ≈ 1 : 1（用户可在界面手动改）\n      setVal('s4_die', total/2);\n      setVal('s4_screen', total/2);\n      filled.push('刀模丝网(默认均分):'+m[1]);\n    }\n  }\n\n  m = take(/(?:零头修正|零头|零)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*%?/);\n  if(m) { setVal('s4_fractionAdj', m[1]); filled.push('零头:'+m[1]+'%'); }\n\n  m = take(/(?:价格修正|修正|修)\\s*:?\\s*(\\d+(?:\\.\\d+)?)\\s*元?/);\n  if(m) { setVal('s4_priceAdj', m[1]); filled.push('价格修正:'+m[1]); }\n\n  // === 20. 裸数字自动推断 ===\n  // 找出未被关键字消费的独立数字，按顺序自动填入 厚度→克重→数量\n  const bareNums = [];\n  const numRe = /(?:^|\\s)(\\d+(?:\\.\\d+)?)(?=\\s|$)/g;\n  let bm;\n  while((bm = numRe.exec(work)) !== null) {\n    bareNums.push(bm[1]);\n  }\n  if(bareNums.length > 0) {\n    if(!done.has('thickness') && bareNums[0]) {\n      setVal('s1_thickness', bareNums[0]); filled.push('厚度:'+bareNums[0]+'(自动)'); bareNums.shift();\n    }\n    if(!done.has('weight') && bareNums[0]) {\n      setVal('s1_weight', bareNums[0]); filled.push('克重:'+bareNums[0]+'(自动)'); bareNums.shift();\n    }\n    if(!done.has('quantity') && bareNums[0]) {\n      setVal('s1_quantity', bareNums[0]); filled.push('数量:'+bareNums[0]+'(自动)'); bareNums.shift();\n    }\n  }\n\n  // === 17. 客户收货地址（关键词匹配 + 兜底用剩余 work）===\n  let addr = '';\n  let am = work.match(/(?:客户收货地址|收货地址|地址|收货)\\s*[:：]?\\s*([^\\d]{3,80}?)(?=\\s*[\\d×xX\\*]|$)/);\n  if(am) {\n    addr = am[1].trim();\n    work = work.replace(am[0], ' ');\n  } else {\n    // 兜底：取剩余 work，去掉明显残留的数字/单位\n    let rest = work.trim().replace(/\\s+/g, ' ');\n    if(rest && rest.length >= 4 && !/^[\\d.×xX\\*%\\s]+$/.test(rest) && !/(普通|含税|不含税|回料|新料|母料|防静电|导电|耐低温|阻燃)/.test(rest)) {\n      addr = rest;\n    }\n  }\n  if(addr) {\n    setVal('s1_address', addr);\n    filled.push('地址:' + addr);\n  }\n\n  calcAll();\n  showParseResult(filled);\n}\n\nfunction clickStyle(style) {\n  const chip = document.querySelector('.type-chip[data-style=\"'+style+'\"]');\n  if(chip) chip.click();\n}\nfunction clickDimType(dim) {\n  const chip = document.querySelector('#s1_dimtype_row .type-chip[data-dim=\"'+dim+'\"]');\n  if(chip) chip.click();\n}\nfunction clickMatType(type) {\n  const chip = document.querySelector('#s2_type_row .type-chip[data-type=\"'+type+'\"]');\n  if(chip) chip.click();\n}\nfunction setVal(id, v) {\n  const el = document.getElementById(id);\n  if(el) el.value = v;\n}\nfunction setSelect(id, v) {\n  const el = document.getElementById(id);\n  if(el) el.value = v;\n}\nfunction checkProcess(key, price) {\n  // 全容器查找（#cb_grid / .cb-trio / #cb_grid2 / #cb_custom_grid），\n  // 此前只查 #cb_grid，导致 .cb-trio 内工序（纤维胶/魔术贴角/骨架箱）文字识别静默失效\n  const item = document.querySelector('.cb-item[data-key=\"'+key+'\"]');\n  if(!item) return;\n  const cb = item.querySelector('input[type=\"checkbox\"]');\n  cb.checked = true;\n  if(price !== undefined) {\n    const numInput = item.querySelector('input[type=\"number\"]');\n    if(numInput){ numInput.value = price; numInput.setAttribute('data-user-set','1'); }\n  }\n}\n\nfunction showParseResult(filled, msg) {\n  const el = document.getElementById('parseResult');\n  if(msg) { el.innerHTML = '<span class=\"fail\">'+escapeHTML(msg)+'</span>'; return; }\n  if(filled.length === 0) {\n    el.innerHTML = '<span class=\"fail\">未识别到有效参数</span>';\n  } else {\n    el.innerHTML = '<span class=\"ok\">✓ 已填写 '+filled.length+' 项：</span>' + escapeHTML(filled.join(' · '));\n  }\n}\n\n// ==================== Init ====================\n// 价格字段：用户手动输入时标记为\"已填\"，类型切换时保留\n['s2_newPrice','s2_masterPrice','s2_specialPrice','s2_fixedCost'].forEach(id => {\n  const el = document.getElementById(id);\n  if(el) el.addEventListener('input', () => el.setAttribute('data-user-set','1'));\n});\n// 先保存出厂快照并显示本地配置，云端响应慢时也能开始使用。\ncaptureDefaults();\nsyncStyleUI();\ncalcAll();\nlet startupEdited = false;\nfunction trackStartupEdit(event){\n  if(event.target.closest('input, select, .type-chip')) startupEdited = true;\n}\nconst startupEvents = ['input', 'change', 'click'];\nstartupEvents.forEach(type => document.addEventListener(type, trackStartupEdit));\nloadSharedTemplate().finally(() => {\n  startupEvents.forEach(type => document.removeEventListener(type, trackStartupEdit));\n  if(!sharedTemplate) return;\n  if(startupEdited){\n    showSyncBanner(sharedTemplate);\n  } else {\n    captureDefaults();\n    syncStyleUI();\n    calcAll();\n  }\n});\n// 标签页切回前台时检测是否有新共享模板（同事开着页面也能收到更新提示）\ndocument.addEventListener('visibilitychange', () => {\n  if(document.visibilityState === 'visible') checkSharedTemplateUpdate();\n});\ndocument.addEventListener('keydown', e=>{ if(e.key==='Escape') closePrintSheet(); });\n\n// ==================== 打印报价单 ====================\nvar _printParts = null;\nvar _printOption = 'verify';\n\nfunction selectPrintOpt(opt){\n  _printOption = opt;\n  document.querySelectorAll('.ps-opt').forEach(b=>b.classList.toggle('active', b.dataset.opt===opt));\n  renderPrintSheet();\n}\nfunction renderPrintSheet(){\n  if(!_printParts) return;\n  let html = '';\n  if(_printOption==='verify' || _printOption==='all') html += _printParts.verify;\n  if(_printOption==='customer' || _printOption==='all'){\n    if(_printOption==='all') html += '<div class=\"ps-divider\"></div>';\n    html += _printParts.customer;\n  }\n  document.getElementById('printSheetContent').innerHTML = html;\n  document.getElementById('ps_date').textContent = _printParts.dateTxt;\n}\n\n// ===== 构建打印内容（提取为独立函数，供 openPrintSheet 和 exportExcel 共用）=====\nfunction buildPrintParts(){\n  const r1=calcStep1(), r2=calcStep2(r1), r3=calcStep3(r2), r4=calcStep4(r3);\n  const dimTxt = (state.dimType==='外尺')?'外尺':'内尺';\n  const _isBoxCat = state.style === '' && state.boxCat;\n  const _isPlateDisc = ['板材','圆盘'].includes(state.style);\n  const styleGroup = state.style === '投票箱' || state.caseCat ? '盒子' : '箱子';\n  const styleShow = _isPlateDisc ? state.style : (_isBoxCat || !state.style ? styleGroup : (styleGroup+'/'+state.style+(state.dimType ? ' / '+dimTxt : '')));\n  const now = new Date();\n  const dateTxt = now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');\n\n  // 税率相关变量（必须在所有模板引用之前声明）\n  const taxLabel = document.getElementById('s1_tax').value === '是' ? '含税' : '不含税';\n  const taxRate = +val('s1_taxRate');\n\n  // —— 先声明所有模板中引用的变量（必须在 const 模板之前）——\n  // 左侧：后加工工序列表行（屏幕/PDF 用）\n  let procRows = '';\n  r3.details.forEach(d=>{\n    const showPrice = (taxLabel==='含税') ? d.price*(1+taxRate/100) : d.price;\n    procRows += `<tr data-label=\"${escapeHTML(d.name)}\"><td>${escapeHTML(d.name)}</td><td class=\"num\">${fmt(showPrice,3)}</td></tr>`;\n  });\n  if(procRows==='') procRows = '<tr><td colspan=\"2\" style=\"text-align:center;color:#999;padding:4px 0;\">（未勾选）</td></tr>';\n\n  // 客户联：后加工工序只显示名称，不带价格（屏幕/PDF 用）\n  let procRowsCustomer = '';\n  r3.details.forEach(d=>{ procRowsCustomer += `<tr data-label=\"${escapeHTML(d.name)}\"><td>${escapeHTML(d.name)}</td></tr>`; });\n  if(procRowsCustomer==='') procRowsCustomer = '<tr><td style=\"text-align:center;color:#999;padding:4px 0;\">（未勾选）</td></tr>';\n\n  // Excel 导出专用：后加工工序行（内联样式）\n  let procRowsExcel = '';\n  r3.details.forEach(d=>{\n    const showPrice = (taxLabel==='含税') ? d.price*(1+taxRate/100) : d.price;\n    procRowsExcel += `<tr data-label=\"${escapeHTML(d.name)}\"><td style=\"width:70%;color:#555;border-bottom:1px dotted #eee;padding:3px 0;\">${escapeHTML(d.name)}</td><td style=\"width:30%;text-align:right;font-weight:600;color:#0f172a;border-bottom:1px dotted #eee;padding:3px 0;\">${fmt(showPrice,3)}</td></tr>`;\n  });\n  if(procRowsExcel==='') procRowsExcel = '<tr><td colspan=\"2\" style=\"text-align:center;color:#999;padding:4px 0;border-bottom:1px dotted #eee;\">（未勾选）</td></tr>';\n\n  // Excel 导出专用：客户联后加工工序行（内联样式，不带价格）\n  let procRowsCustomerExcel = '';\n  r3.details.forEach(d=>{ procRowsCustomerExcel += `<tr data-label=\"${escapeHTML(d.name)}\"><td style=\"width:100%;color:#555;border-bottom:1px dotted #eee;padding:3px 0;\">${escapeHTML(d.name)}</td></tr>`; });\n  if(procRowsCustomerExcel==='') procRowsCustomerExcel = '<tr><td style=\"text-align:center;color:#999;padding:4px 0;border-bottom:1px dotted #eee;\">（未勾选）</td></tr>';\n\n  // 中间变量\n  const shipFeeLabel = document.getElementById('s1_shipFee').value === '是' ? '含运' : '不含运';\n  const addressVal = escapeHTML((document.getElementById('s1_address').value || '').trim() || '—');\n  const areaVal = fmt(r1.L, 3);\n  const qty = fmt(r1.H, 0);\n  const thick = fmt(+val('s1_thickness'), 2);\n  const weightG = fmt(+val('s1_weight'), 1);\n  const dieVal = fmt(+val('s4_die'), 2);\n  const screenVal = fmt(+val('s4_screen'), 2);\n  const moldSum = (+val('s4_die')||0) + (+val('s4_screen')||0);\n  const perExtra = r1.H > 0 ? (r4.E + moldSum) / r1.H : 0;\n\n  // —— 客户联：参考计算联，仅左(已知条件)+右(计算结果) 双栏 ——\n  const customer = `\n    <div class=\"ps-section verify customer\">\n      <div class=\"calc-trio\">\n\n        <!-- 左：已知条件 -->\n        <div class=\"calc-col calc-left\">\n          <div class=\"calc-head\">已知条件</div>\n          <div class=\"calc-list\">\n            <div class=\"calc-row print-line\"><span>产品样式</span><b>${escapeHTML(styleShow)}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>原料配方</span><b>${escapeHTML(state.materialType)}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-sub print-line\"><span>新料比例</span><b>${fmt(+val('s2_newRatio'),0)}%</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-sub print-line\"><span>母料比例</span><b>${fmt(+val('s2_masterRatio'),0)}%</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-sub print-line\"><span>特殊料比例</span><b>${fmt(+val('s2_specialRatio'),0)}%</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>厚度</span><b>${thick} mm</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>克重</span><b>${weightG} g/㎡</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>尺寸</span><b>${dimShow(r1)} mm</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n          </div>\n          <div class=\"calc-subtitle\">后加工工序</div>\n          <table class=\"calc-proc-table\"><tbody>${procRowsCustomer}</tbody></table>\n          <div class=\"calc-subtitle\">附加情况</div>\n          <div class=\"calc-list\" style=\"margin-top:6px\">\n            <div class=\"calc-row print-line\"><span>运费总计</span><b>${fmt(r4.E,2)} 元</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>刀模费</span><b>${dieVal} 元</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>丝网费</span><b>${screenVal} 元</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>零头修正</span><b>${fmt(r4.G*100,0)} %</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row print-line\"><span>价格修正</span><b>${fmt(r4.H,2)} 元</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n          </div>\n        </div>\n\n        <!-- 右：计算结果 -->\n        <div class=\"calc-col calc-right\">\n          <div class=\"calc-head\">计算结果</div>\n          <div class=\"calc-list\">\n            <div class=\"calc-row calc-row-big print-line\"><span>最终单价</span><b>￥${fmt(r4.I,3)} /个</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>数量</span><b>${qty} 个</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>大货总价</span><b>￥${fmt(r4.J,2)}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>是否含税</span><b>${taxLabel}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>总体积</span><b>${fmt(r1.M,2)} m³</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>总吨数</span><b>${fmt(r1.N,2)} T</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>是否含运</span><b>${shipFeeLabel}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n            <div class=\"calc-row calc-row-big print-line\"><span>客户收货地址</span><b style=\"word-break:break-all;white-space:normal;\">${addressVal}</b><button class=\"line-hide-btn\" onclick=\"togglePrintLine(this)\">隐藏</button></div>\n          </div>\n        </div>\n\n      </div>\n    </div>`;\n\n  // —— 计算联：左中右三栏 ——\n  // 板材长/宽的推导公式（按样式类型）\n  const E=+val('s1_length'), F=+val('s1_width'), G=+val('s1_height');\n  const isInner = state.dimType === '内尺';\n  const styleK = state.style||'';\n  let Loff=0, Woff=0;\n  let boardLNum='', boardWNum='';\n  let board2LNum='', board2WNum='';\n  if(styleK==='圆盘'){\n    boardLNum=fmt(E,0)+'+10';\n    boardWNum=fmt(E,0)+'+10';\n  } else if(styleK==='纸箱式'){\n    Loff = isInner?35:10; Woff = isInner?60:45;\n    boardLNum=fmt(F,0)+'+'+fmt(G,0)+'+'+Loff;\n    boardWNum=fmt(E,0)+'+'+fmt(F,0)+'+'+Woff;\n  } else if(styleK==='插底式'){\n    Loff = isInner?95:70; Woff = isInner?60:45;\n    boardLNum=fmt(F,0)+'+'+fmt(G,0)+'+'+Loff;\n    boardWNum=fmt(E,0)+'+'+fmt(F,0)+'+'+Woff;\n  } else if(styleK==='焊底式'){\n    Loff = isInner?35:10; Woff = isInner?60:45;\n    // 板材1\n    boardLNum=fmt(F,0)+'+'+fmt(G,0)+'+'+Loff;\n    boardWNum=fmt(E,0)+'+'+fmt(F,0)+'+'+Woff;\n    // 板材2\n    board2LNum='1.5×'+fmt(F,0)+'+'+fmt(G,0)+'+'+Loff;\n    board2WNum=fmt(E,0)+'+'+fmt(F,0)+'+'+Woff;\n  } else if(styleK==='投票箱'){\n    boardLNum=fmt(G,0)+'+2×'+fmt(F,0)+'+70';\n    boardWNum=fmt(E,0)+'+10';\n    board2LNum=fmt(G,0)+'+100';\n    board2WNum=fmt(E,0)+'+2×'+fmt(F,0)+'+70';\n  } else if(styleK==='四拼式'){\n    // 板材1：长① = 宽+高+加放量，宽① = 长+90（内外尺同）\n    const _so = isInner?35:10, _wo = isInner?25:10;\n    boardLNum=fmt(F,0)+'+'+fmt(G,0)+'+'+_so;\n    boardWNum=fmt(E,0)+'+90';\n    // 板材2：长② = 宽+高+加放量（与板材长①相同），宽② = 宽+10（外尺）/ 宽+25（内尺）\n    board2LNum=fmt(F,0)+'+'+fmt(G,0)+'+'+_so;\n    board2WNum=fmt(F,0)+'+'+_wo;\n  } else if(styleK==='板材'){\n    boardLNum=fmt(E,0);\n    boardWNum=fmt(F,0);\n  } else if(styleK==='骨架箱'){\n    Loff = isInner?25:10; Woff = isInner?25:10;\n    boardLNum=fmt(F,0)+'+2×'+fmt(G,0)+'+'+Loff;\n    const _jNum = (0.5*F<G) ? (fmt(E,0)+'+2×'+fmt(G,0)+'+'+Loff) : (fmt(E,0)+'+'+fmt(F,0)+'+'+Woff);\n    boardWNum=_jNum;\n  } else if(styleK==='全包式'){\n    Loff = isInner?35:10; Woff = isInner?60:45;\n    boardLNum='2×'+fmt(F,0)+'+'+fmt(G,0)+'+'+Loff;\n    boardWNum=fmt(E,0)+'+'+fmt(F,0)+'+'+Woff;\n  } else {\n    boardLNum='—';\n    boardWNum='—';\n  }\n\n  // 体积调整系数（与 calcStep1 计算保持一致）\n  let volCoef = '';\n  if(styleK==='焊底式'){ volCoef = '×2'; }\n  else if(styleK==='四拼式'){ volCoef = '×'+SI_PIN_VOL_COEF; }\n  else if(styleK==='纸箱式' || styleK==='插底式' || styleK==='全包式' || styleK==='投票箱'){ volCoef = '×1.25'; }\n\n  // ① 体量计算的展示块（焊底式/四拼式需要显示两块板材，其他样式只显示一块）\n  // 箱类未选外尺/内尺：① 体量计算整个不渲染\n  const _printNeedDim = BOX_STYLES.includes(state.style);\n  const _noDim = _printNeedDim && !state.dimType;\n  const _is2Board = (styleK==='焊底式' || styleK==='四拼式' || styleK==='投票箱');\n  const _board1Tag = _is2Board ? '<b>板材1</b>' : '';\n  const _board2Tag = '<b>板材2</b>';\n  const board1Step = _noDim ? '' : `\n<div class=\"calc-step\">${_board1Tag}</div>\n<div class=\"calc-step\"><span>板材长</span> = ${boardLNum} = <b>${fmt(_is2Board?r1.Im:r1.I,1)} mm</b></div>\n<div class=\"calc-step\"><span>板材宽</span> = ${boardWNum} = <b>${fmt(_is2Board?r1.Jm:r1.J,1)} mm</b></div>`;\n  const board2Step = (_is2Board && !_noDim) ? `\n<div class=\"calc-step\">${_board2Tag}</div>\n<div class=\"calc-step\"><span>板材长</span> = ${board2LNum} = <b>${fmt(r1.Ia,1)} mm</b></div>\n<div class=\"calc-step\"><span>板材宽</span> = ${board2WNum} = <b>${fmt(r1.Ja,1)} mm</b></div>` : '';\n  const areaStep = _noDim ? '' : (styleK==='焊底式' || styleK==='投票箱')\n    ? `<div class=\"calc-step\"><span>单产品面积</span> = (${fmt(r1.Im,1)}×${fmt(r1.Jm,1)} + ${fmt(r1.Ia,1)}×${fmt(r1.Ja,1)})×${fmt(r1.ur*100,0)}% = <b>${areaVal} ㎡</b></div>`\n    : styleK==='四拼式'\n      ? `<div class=\"calc-step\"><span>单产品面积</span> = (2×${fmt(r1.Im,1)}×${fmt(r1.Jm,1)} + 2×${fmt(r1.Ia,1)}×${fmt(r1.Ja,1)})×${fmt(r1.ur*100,0)}% = <b>${areaVal} ㎡</b></div>`\n    : styleK==='圆盘'\n      ? `<div class=\"calc-step\"><span>单产品面积</span> = (π×(${fmt(E/2,1)})² − π×(${fmt(F/2,1)})²) ÷ 10⁶ = <b>${areaVal} ㎡</b></div>`\n      : (styleK==='纸箱式'||styleK==='插底式'||styleK==='全包式')\n        ? `<div class=\"calc-step\"><span>单产品面积</span> = ${fmt(r1.I,1)}×${fmt(r1.J,1)}×2×${fmt(r1.ur*100,0)}%÷10⁶ = <b>${areaVal} ㎡</b></div>`\n        : styleK==='骨架箱'\n          ? `<div class=\"calc-step\"><span>单产品面积</span> = ${fmt(r1.I,1)}×${fmt(r1.J,1)}×${fmt(r1.ur*100,0)}%÷10⁶ = <b>${areaVal} ㎡</b></div>`\n          : `<div class=\"calc-step\"><span>单产品面积</span> = ${fmt(r1.I,1)}×${fmt(r1.J,1)}×${fmt(r1.K,2)} = <b>${areaVal} ㎡</b></div>`;\n  const dimHint = _noDim ? '<div class=\"calc-step\" style=\"color:#9ca3af;\">（请先选择「外尺」或「内尺」）</div>' : '';\n  // 圆盘下：calcStep1 的\"总立方数\"公式是\"外直径²×厚度×数量÷1e9\"（按整圆算），不能用 areaVal(圆环面积)×thick\n  const totalCubStep = _noDim ? '' : styleK==='圆盘'\n    ? `<div class=\"calc-step\"><span>总立方数</span> = ${fmt(E,0)}²×${thick}×${qty}÷1e9 = <b>${fmt(r1.M,2)} m³</b></div>`\n    : styleK==='骨架箱'\n      ? `<div class=\"calc-step\"><span>总立方数</span> = ${fmt(E,0)}×${fmt(F,0)}×${fmt(G,0)}×${qty}÷1e9 = <b>${fmt(r1.M,2)} m³</b></div>`\n      : `<div class=\"calc-step\"><span>总立方数</span> = ${areaVal}×${thick}${volCoef}×${qty}÷1000 = <b>${fmt(r1.M,2)} m³</b></div>`;\n  const totalTonStep = _noDim ? '' : `<div class=\"calc-step\"><span>总吨数</span> = ${areaVal}×${weightG}×${qty}÷1e6 = <b>${fmt(r1.N,2)} T</b></div>`;\n\n  const calcSteps = `\n<div class=\"calc-step\"><b>① 体量计算</b></div>\n${board1Step}${board2Step}${areaStep}${totalCubStep}${totalTonStep}${dimHint}\n<div class=\"calc-step\"><b>② 原料/板材价格计算</b></div>\n${(()=>{\n  const taxFlag = taxLabel==='含税';\n  const FP = fmt(+val('s2_masterRatio'),0), GP = fmt(+val('s2_specialRatio'),0);\n  const RFP = fmt(100 - +val('s2_masterRatio') - +val('s2_specialRatio'),0);\n  const Np = fmt(+val('s2_newPrice'),0), Op = fmt(+val('s2_masterPrice'),0), Pp = fmt(+val('s2_specialPrice'),0);\n  const Qp = fmt(+val('s2_fixedCost'),0), Rp = fmt(+val('s2_profit'),0);\n  const costNum = taxFlag\n    ? (FP+'%×'+Op+'+'+GP+'%×'+Pp+'+'+RFP+'%×'+Np)\n    : ('('+FP+'%×'+Op+'+'+GP+'%×'+Pp+'+'+RFP+'%×'+Np+')×0.93');\n  const priceNum = taxFlag\n    ? ('('+Qp+'+'+fmt(r2.S,0)+'+'+Rp+')×(1+'+fmt(taxRate,0)+'%)')\n    : (fmt(r2.S,0)+'+'+Qp+'+'+Rp);\n  return `\n<div class=\"calc-step\"><span>原料成本</span> = ${costNum} = <b>${fmt(r2.S,0)} 元/吨</b></div>\n<div class=\"calc-step\"><span>原料售价</span> = ${priceNum} = <b>${fmt(r2.T,0)} 元/吨</b></div>\n<div class=\"calc-step\"><span>板材售价（单）</span> = ${areaVal}×${weightG}×${fmt(r2.T,0)}÷1e6 = <b>${fmt(r2.V,3)} 元</b></div>`;\n})()}\n<div class=\"calc-step\"><b>③ 后加工价格计算</b></div>\n${(()=>{\n  if(r3.details && r3.details.length>0){\n    const detailNum = r3.details.map(d=>fmt(d.price,3)+'('+escapeHTML(d.name)+')').join('+');\n    const procExpr = (taxLabel==='含税') ? ('('+detailNum+')×(1+'+fmt(taxRate,0)+'%)') : detailNum;\n    return `<div class=\"calc-step\"><span>后加工费用合计</span> = ${procExpr} = <b>${fmt(r3.sum,3)} 元</b></div>\n<div class=\"calc-step\"><span>成品价格（单）</span> = ${fmt(r3.sheetUnitPrice,3)}+${fmt(r3.sum,3)} = <b>${fmt(r3.productUnitPrice,3)} 元</b></div>`;\n  }\n  return `<div class=\"calc-step\"><span>后加工费用合计</span> = 0 = <b>${fmt(r3.sum,3)} 元</b></div>\n<div class=\"calc-step\"><span>成品价格（单）</span> = ${fmt(r3.sheetUnitPrice,3)}+${fmt(r3.sum,3)} = <b>${fmt(r3.productUnitPrice,3)} 元</b></div>`;\n})()}\n<div class=\"calc-step\"><b>④ 附加费用计算</b></div>\n${r1.H>0 ? `<div class=\"calc-step\"><span>(运费+刀模费+丝网费)/数量</span> = (${fmt(r4.E,2)}+${fmt(r4.F,2)}+${fmt(r4.Fa,2)})÷${qty} = <b>${fmt(perExtra, 3)} 元/个</b></div>` : `<div class=\"calc-step\"><span>(运费+刀模费+丝网费)/数量</span> = <b>0 元/个</b></div>`}\n<div class=\"calc-step\"><span>最终报价（单）</span> = ${r4.A==='是'?(fmt(r4.D,2)+'×(1+'+fmt(r4.G*100,0)+'%)+('+fmt(perExtra,3)+'+'+fmt(r4.H,2)+')×(1+'+fmt(r4.B*100,0)+'%)'):(fmt(r4.D,2)+'×(1+'+fmt(r4.G*100,0)+'%)+'+fmt(perExtra,3)+'+'+fmt(r4.H,2))} = <b>${fmt(r4.I,3)} 元/个</b></div>\n<div class=\"calc-step\"><span>最终报价（总）</span> = ${fmt(r4.I,3)}×${qty} = <b>${fmt(r4.J,2)} 元</b></div>`;\n\n  const verify = `\n    <div class=\"ps-section verify\">\n      <div class=\"calc-trio\">\n\n        <!-- 左：已知条件 -->\n        <div class=\"calc-col calc-left\">\n          <div class=\"calc-head\">已知条件</div>\n          <div class=\"calc-list\">\n            <div class=\"calc-row\"><span>产品样式</span><b>${escapeHTML(styleShow)}</b></div>\n            <div class=\"calc-row\"><span>原料配方</span><b>${escapeHTML(state.materialType)}</b></div>\n            <div class=\"calc-row calc-row-sub\"><span>新料比例</span><b>${fmt(+val('s2_newRatio'),0)}%</b></div>\n            <div class=\"calc-row calc-row-sub\"><span>母料比例</span><b>${fmt(+val('s2_masterRatio'),0)}%</b></div>\n            <div class=\"calc-row calc-row-sub\"><span>特殊料比例</span><b>${fmt(+val('s2_specialRatio'),0)}%</b></div>\n            <div class=\"calc-row\"><span>厚度</span><b>${thick} mm</b></div>\n            <div class=\"calc-row\"><span>克重</span><b>${weightG} g/㎡</b></div>\n            <div class=\"calc-row\"><span>尺寸</span><b>${dimShow(r1)} mm</b></div>\n          </div>\n          <div class=\"calc-subtitle\">后加工工序</div>\n          <table class=\"calc-proc-table\"><tbody>${procRows}</tbody></table>\n          <div class=\"calc-subtitle\">附加情况</div>\n          <div class=\"calc-list\" style=\"margin-top:6px\">\n            <div class=\"calc-row\"><span>运费总计</span><b>${fmt(r4.E,2)} 元</b></div>\n            <div class=\"calc-row\"><span>刀模费</span><b>${dieVal} 元</b></div>\n            <div class=\"calc-row\"><span>丝网费</span><b>${screenVal} 元</b></div>\n            <div class=\"calc-row\"><span>零头修正</span><b>${fmt(r4.G*100,0)} %</b></div>\n            <div class=\"calc-row\"><span>价格修正</span><b>${fmt(r4.H,2)} 元</b></div>\n          </div>\n        </div>\n\n        <!-- 中：计算过程 -->\n        <div class=\"calc-col calc-mid\">\n          <div class=\"calc-head\">计算过程</div>\n          <div class=\"calc-list\">\n            ${calcSteps}\n          </div>\n        </div>\n\n        <!-- 右：计算结果 -->\n        <div class=\"calc-col calc-right\">\n          <div class=\"calc-head\">计算结果</div>\n          <div class=\"calc-list\">\n            <div class=\"calc-row calc-row-big\"><span>最终单价</span><b>￥${fmt(r4.I,3)} /个</b></div>\n            <div class=\"calc-row calc-row-big\"><span>数量</span><b>${qty} 个</b></div>\n            <div class=\"calc-row calc-row-big\"><span>大货总价</span><b>￥${fmt(r4.J,2)}</b></div>\n            <div class=\"calc-row calc-row-big\"><span>是否含税</span><b>${taxLabel}</b></div>\n            <div class=\"calc-row calc-row-big\"><span>总体积</span><b>${fmt(r1.M,2)} m³</b></div>\n            <div class=\"calc-row calc-row-big\"><span>总吨数</span><b>${fmt(r1.N,2)} T</b></div>\n            <div class=\"calc-row calc-row-big\"><span>是否含运</span><b>${shipFeeLabel}</b></div>\n            <div class=\"calc-row calc-row-big\"><span>客户收货地址</span><b style=\"word-break:break-all;white-space:normal;\">${addressVal}</b></div>\n          </div>\n        </div>\n\n      </div>\n    </div>`;\n\n  // ===== Excel 导出专用 table 排版（与 PDF 视觉一致，全部内联样式） =====\n  const excelStyle = `\n    <style>\n      table { border-collapse:collapse; font-family:\"Microsoft YaHei\", sans-serif; font-size:12px; color:#0f172a; }\n      td, th { vertical-align:top; border:1px solid #cbd5e1; padding:4px 6px; }\n      br { mso-data-placement:same-cell; }\n    </style>`;\n\n  // 左栏：已知条件（Excel 内联样式）\n  const leftRowsExcel = `\n    <tr data-label=\"产品样式\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">产品样式</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${escapeHTML(styleShow)}</td></tr>\n    <tr data-label=\"原料配方\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">原料配方</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${escapeHTML(state.materialType)}</td></tr>\n    <tr data-label=\"新料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">新料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_newRatio'),0)}%</td></tr>\n    <tr data-label=\"母料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">母料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_masterRatio'),0)}%</td></tr>\n    <tr data-label=\"特殊料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">特殊料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_specialRatio'),0)}%</td></tr>\n    <tr data-label=\"厚度\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">厚度</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${thick} mm</td></tr>\n    <tr data-label=\"克重\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">克重</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${weightG} g/㎡</td></tr>\n    <tr data-label=\"尺寸\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">尺寸</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${dimShow(r1)} mm</td></tr>\n    <tr><td colspan=\"2\" style=\"font-weight:700;color:#475569;border-bottom:1px solid #e2e8f0;padding:8px 0 3px;\">后加工工序</td></tr>\n    ${procRowsExcel}\n    <tr><td colspan=\"2\" style=\"font-weight:700;color:#475569;border-bottom:1px solid #e2e8f0;padding:8px 0 3px;\">附加情况</td></tr>\n    <tr data-label=\"运费总计\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">运费总计</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.E,2)} 元</td></tr>\n    <tr data-label=\"刀模费\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">刀模费</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${dieVal} 元</td></tr>\n    <tr data-label=\"丝网费\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">丝网费</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${screenVal} 元</td></tr>\n    <tr data-label=\"零头修正\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">零头修正</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.G*100,0)} %</td></tr>\n    <tr data-label=\"价格修正\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">价格修正</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.H,2)} 元</td></tr>`;\n\n  // 右栏：计算结果 8 项（Excel 内联样式）\n  const rightRowsExcel = `\n    <tr data-label=\"最终单价\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">最终单价</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">￥${fmt(r4.I,3)} /个</td></tr>\n    <tr data-label=\"数量\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">数量</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">${qty} 个</td></tr>\n    <tr data-label=\"大货总价\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">大货总价</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">￥${fmt(r4.J,2)}</td></tr>\n    <tr data-label=\"是否含税\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">是否含税</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">${taxLabel}</td></tr>\n    <tr data-label=\"总体积\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">总体积</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">${fmt(r1.M,2)} m³</td></tr>\n    <tr data-label=\"总吨数\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">总吨数</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">${fmt(r1.N,2)} T</td></tr>\n    <tr data-label=\"是否含运\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">是否含运</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;\">${shipFeeLabel}</td></tr>\n    <tr data-label=\"客户收货地址\"><td style=\"font-size:14px;color:#555;width:40%;border-bottom:1px solid #e2e8f0;padding:6px 0;\">客户收货地址</td><td style=\"font-size:14px;font-weight:600;text-align:right;color:#be123c;font-size:16px;border-bottom:1px solid #e2e8f0;padding:6px 0;word-break:break-all;\">${addressVal}</td></tr>`;\n\n  // 中栏：计算过程（Excel 内联样式）\n  const stepLinesExcel = calcSteps.split('</div>').filter(s=>s.trim()).map(s=>{\n    const bMatch = s.match(/<b>(.*?)<\\/b>/);\n    const bText = bMatch ? bMatch[1] : '';\n    let label = s.replace(/<b>.*?<\\/b>/,'').replace(/<[^>]+>/g,'').replace(/=/g,'').trim();\n    if(label.endsWith('：') || label.endsWith(':')) label = label.slice(0,-1);\n    return `<tr><td style=\"color:#94a3b8;font-size:11px;border-bottom:1px dotted #eee;padding:3px 0;\">${label}</td><td style=\"font-weight:700;color:#0369a1;border-bottom:1px dotted #eee;padding:3px 0;\">${bText}</td></tr>`;\n  }).join('');\n\n  const verifyExcel = `${excelStyle}\n<table>\n  <tr>\n    <td style=\"width:28%;font-size:13px;font-weight:700;color:#0369a1;background:#fff;border-bottom:2px solid #0369a1;\">已知条件</td>\n    <td style=\"width:44%;font-size:13px;font-weight:700;color:#0369a1;background:#fff;border-bottom:2px solid #0369a1;\">计算过程</td>\n    <td style=\"width:28%;font-size:13px;font-weight:700;color:#be123c;background:#fff;border-bottom:2px solid #be123c;\">计算结果</td>\n  </tr>\n  <tr>\n    <td><table style=\"width:100%;border:none;\">${leftRowsExcel}</table></td>\n    <td><table style=\"width:100%;border:none;\">${stepLinesExcel}</table></td>\n    <td><table style=\"width:100%;border:none;\">${rightRowsExcel}</table></td>\n  </tr>\n</table>`;\n\n  // 客户联左栏（Excel 内联样式）\n  const leftRowsCustomerExcel = `\n    <tr data-label=\"产品样式\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">产品样式</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${escapeHTML(styleShow)}</td></tr>\n    <tr data-label=\"原料配方\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">原料配方</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${escapeHTML(state.materialType)}</td></tr>\n    <tr data-label=\"新料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">新料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_newRatio'),0)}%</td></tr>\n    <tr data-label=\"母料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">母料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_masterRatio'),0)}%</td></tr>\n    <tr data-label=\"特殊料比例\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0 3px 12px;\">特殊料比例</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(+val('s2_specialRatio'),0)}%</td></tr>\n    <tr data-label=\"厚度\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">厚度</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${thick} mm</td></tr>\n    <tr data-label=\"克重\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">克重</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${weightG} g/㎡</td></tr>\n    <tr data-label=\"尺寸\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">尺寸</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${dimShow(r1)} mm</td></tr>\n    <tr><td colspan=\"2\" style=\"font-weight:700;color:#475569;border-bottom:1px solid #e2e8f0;padding:8px 0 3px;\">后加工工序</td></tr>\n    ${procRowsCustomerExcel}\n    <tr><td colspan=\"2\" style=\"font-weight:700;color:#475569;border-bottom:1px solid #e2e8f0;padding:8px 0 3px;\">附加情况</td></tr>\n    <tr data-label=\"运费总计\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">运费总计</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.E,2)} 元</td></tr>\n    <tr data-label=\"刀模费\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">刀模费</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${dieVal} 元</td></tr>\n    <tr data-label=\"丝网费\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">丝网费</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${screenVal} 元</td></tr>\n    <tr data-label=\"零头修正\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">零头修正</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.G*100,0)} %</td></tr>\n    <tr data-label=\"价格修正\"><td style=\"color:#555;width:40%;border-bottom:1px solid #eee;padding:3px 0;\">价格修正</td><td style=\"font-weight:600;text-align:right;color:#0f172a;border-bottom:1px solid #eee;padding:3px 0;\">${fmt(r4.H,2)} 元</td></tr>`;\n\n  const customerExcel = `${excelStyle}\n<table>\n  <tr>\n    <td style=\"width:50%;font-size:13px;font-weight:700;color:#0369a1;background:#fff;border-bottom:2px solid #0369a1;\">已知条件</td>\n    <td style=\"width:50%;font-size:13px;font-weight:700;color:#be123c;background:#fff;border-bottom:2px solid #be123c;\">计算结果</td>\n  </tr>\n  <tr>\n    <td><table style=\"width:100%;border:none;\">${leftRowsCustomerExcel}</table></td>\n    <td><table style=\"width:100%;border:none;\">${rightRowsExcel}</table></td>\n  </tr>\n</table>`;\n\n  return {customer, verify, dateTxt, customerExcel, verifyExcel};\n}\n\nfunction openPrintSheet(){\n  // —— 必填校验：原料利润（元/吨）为空或为 0 时拦截，不打开报价单 ——\n  const profitInput = document.getElementById('s2_profit');\n  const profitRaw = (profitInput.value || '').trim();\n  const profitNum = parseFloat(profitRaw);\n  if(profitRaw === '' || isNaN(profitNum) || profitNum <= 0){\n    showToast('⚠ 「原料利润」为必填项，请填写大于 0 的数值（元/吨）', 'warn');\n    profitInput.style.borderColor = '#dc2626';\n    profitInput.style.boxShadow = '0 0 0 2px rgba(220,38,38,0.15)';\n    profitInput.focus();\n    setTimeout(()=>{ profitInput.style.borderColor = ''; profitInput.style.boxShadow = ''; }, 3000);\n    return;\n  }\n  document.getElementById('printSheetModal').classList.add('show');\n  try {\n    _printParts = buildPrintParts();\n    _printOption = 'verify';\n    document.querySelectorAll('.ps-opt').forEach(b=>b.classList.toggle('active', b.dataset.opt==='verify'));\n    renderPrintSheet();\n  } catch(e) {\n    console.error('报价单生成失败：', e);\n    document.getElementById('printSheetContent').innerHTML = '<div style=\"padding:30px;color:#dc2626;text-align:center;font-size:14px;\">⚠ 报价单生成失败：'+(e&&e.message?e.message:e)+'<br><br>请打开浏览器开发者工具(F12)查看详细错误。</div>';\n  }\n  document.getElementById('printSheetModal').classList.add('show');\n}\nfunction closePrintSheet(){ document.getElementById('printSheetModal').classList.remove('show'); }\nfunction togglePrintLine(el){\n  const row = el.closest('.print-line') || el.closest('.calc-row');\n  if(!row) return;\n  const isHidden = row.classList.toggle('hidden-line');\n  el.textContent = isHidden ? '显示' : '隐藏';\n}\nfunction doPrintSheet(){\n  // 直接打印当前弹窗内容；hidden-line 已是 display:none !important，打印/PDF 自动排除\n  window.print();\n}\nfunction getCleanExcelHTML(){\n  const container = document.getElementById('printSheetContent');\n  if(!container) return '';\n  // 获取当前隐藏行的 label 集合\n  const hiddenLabels = new Set();\n  container.querySelectorAll('.print-line.hidden-line, .calc-row.hidden-line').forEach(row=>{\n    const span = row.querySelector('span');\n    if(span) hiddenLabels.add(span.textContent.trim());\n  });\n  // 使用 buildPrintParts 生成的 table 布局 Excel HTML\n  const parts = _printParts || {};\n  let raw = (_printOption === 'customer' ? parts.customerExcel : parts.verifyExcel) || '';\n  if(!raw) return '';\n  // 分离 <style> 标签和 table 内容（不用 DOMParser，避免 <style> 被移到 head 后丢失）\n  const styleMatch = raw.match(/<style>[\\s\\S]*?<\\/style>/);\n  const styleTag = styleMatch ? styleMatch[0] : '';\n  let tableHTML = raw.replace(/<style>[\\s\\S]*?<\\/style>/, '').trim();\n  // 用正则移除隐藏 label 对应的行\n  if(hiddenLabels.size > 0){\n    tableHTML = tableHTML.replace(/<tr\\s+data-label=\"([^\"]*)\">[\\s\\S]*?<\\/tr>/g, (m, label)=>{\n      return hiddenLabels.has(label) ? '' : m;\n    });\n  }\n  return `<!DOCTYPE html><html><head><meta charset=\"utf-8\">${styleTag}</head><body>${tableHTML}</body></html>`;\n}\nfunction exportVerifyExcel(){\n  // 导出计算联：基于当前 DOM 清理隐藏项后导出\n  downloadExcel(getCleanExcelHTML(), '报价单_计算联_'+(_printParts&&_printParts.dateTxt?_printParts.dateTxt:new Date().toISOString().slice(0,10))+'.xls');\n}\nfunction exportCustomerExcel(){\n  // 导出客户联：基于当前 DOM 清理隐藏项后导出\n  downloadExcel(getCleanExcelHTML(), '报价单_客户联_'+(_printParts&&_printParts.dateTxt?_printParts.dateTxt:new Date().toISOString().slice(0,10))+'.xls');\n}\nfunction exportCurrentExcel(){\n  // 根据当前打印内容选项导出对应联\n  const opt = _printOption || 'verify';\n  if(opt === 'customer'){\n    exportCustomerExcel();\n  } else {\n    exportVerifyExcel();\n  }\n}\nfunction downloadExcel(html, filename){\n  const blob = new Blob([html],{type:'application/vnd.ms-excel'});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);\n}\n\nfunction dimShow(r1){\n  const s = state.style;\n  if(s==='板材') return fmt(r1.E,1)+'×'+fmt(r1.F,1);\n  if(s==='圆盘') return fmt(r1.E,1)+'×'+fmt(r1.F,1);\n  if(BOX_STYLES.includes(s)) return fmt(r1.E,1)+'×'+fmt(r1.F,1)+'×'+fmt(r1.G,1);\n  return fmt(r1.E,1)+'×'+fmt(r1.F,1)+(r1.G ? '×'+fmt(r1.G,1) : '');\n}\n\n// ===== 鉴权 / 权限（密码登录）=====\nasync function checkAuth(){\n  const pwd = document.getElementById('authPwd').value;\n  const err = document.getElementById('authErr');\n  err.textContent = '';\n  try {\n    const response = await fetch('/api/login', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ password: pwd })\n    });\n    if(!response.ok){ err.textContent = response.status === 403 ? '密码错误，请重试' : '登录服务暂时不可用，请重试'; return; }\n    sessionStorage.setItem('role', 'admin');\n    sessionStorage.setItem('bh_pwd', pwd);\n    document.getElementById('authOverlay').style.display = 'none';\n    document.getElementById('authPwd').value = '';\n    applyRole();\n  } catch {\n    err.textContent = '网络错误，请重试';\n  }\n}\nfunction applyRole(){\n  const role = sessionStorage.getItem('role')||'employee';\n  document.querySelectorAll('.admin-only').forEach(el=>{ el.style.display = (role==='admin')?'':'none'; });\n}\nfunction saveAsTemplate(){ document.getElementById('tplConfirm').style.display='flex'; }\nfunction confirmReset(){\n  // 文案动态化：有已存模板→恢复模板；没有→恢复出厂默认值，不再产生歧义\n  document.getElementById('resetConfirmText').innerHTML = hasSavedTemplate()\n    ? '确定要重置吗？<br>当前所有输入将被清空，并恢复为<b>已保存的模板</b>。'\n    : '确定要重置吗？<br>当前所有输入将被清空，并恢复为<b>出厂默认值</b>。';\n  document.getElementById('resetConfirm').style.display='flex';\n}\nfunction hideResetConfirm(){ document.getElementById('resetConfirm').style.display='none'; }\nfunction doReset(){\n  document.getElementById('resetConfirm').style.display='none';\n  resetAll();\n}\nfunction doSaveTemplate(){\n  // 收集当前所有值 → 存到 bh_quote_template（与重置模板同一 key，格式对齐 captureDefaults）\n  const flat = {};\n  document.querySelectorAll('input[type=\"number\"], input[type=\"text\"], select').forEach(el=>{ flat[el.id] = el.value; });\n  document.querySelectorAll('input[type=\"checkbox\"]').forEach((el, idx)=>{ flat['cb_'+idx] = el.checked; });\n  flat.style = state.style;\n  flat.dimType = state.dimType;\n  flat.materialType = state.materialType;\n  flat._v = TEMPLATE_VERSION;\n  flat._userSetPrices = Array.from(document.querySelectorAll('[data-user-set=\"1\"]')).map(el=>el.id).filter(Boolean);\n  flat._customCB = getCustomCBData();\n  // 同时记住当前配方类型的自定义价格和比例，下次切换回此配方时恢复\n  const mt = state.materialType;\n  materialPrices[mt] = {\n    newPrice:    parseFloat(document.getElementById('s2_newPrice').value)    || 0,\n    masterPrice: parseFloat(document.getElementById('s2_masterPrice').value) || 0,\n    specialPrice:parseFloat(document.getElementById('s2_specialPrice').value)|| 0,\n    fixedCost:   parseFloat(document.getElementById('s2_fixedCost').value)   || 0,\n    masterRatio: parseFloat(document.getElementById('s2_masterRatio').value) || 0,\n    specialRatio:parseFloat(document.getElementById('s2_specialRatio').value)|| 0,\n    _userSet: Array.from(document.querySelectorAll('[data-user-set=\"1\"]')).map(el=>el.id).filter(Boolean)\n  };\n  // 物化全部原料配方（普通/回料+母料/新料+透明母料/防静电/导电/耐低温/阻燃）的子属性，\n  // 使模板自包含：加载模板后切换到任意配方都能还原其价格与比例\n  const ALL_MATERIAL_TYPES = ['普通','回料+母料','新料+透明母料','防静电','导电','耐低温','阻燃'];\n  ALL_MATERIAL_TYPES.forEach(t => {\n    if(materialPrices[t]) return;            // 已有用户自定义值，原样保留\n    const d = materialDefaults[t];           // 未改过则取出厂默认，确保模板完整\n    if(d){\n      materialPrices[t] = {\n        newPrice:     d.newPrice,\n        masterPrice:  d.masterPrice,\n        specialPrice: d.specialPrice,\n        fixedCost:    d.fixedCost,\n        masterRatio:  d.masterRatio,\n        specialRatio: d.specialRatio,\n        _userSet: []\n      };\n    }\n  });\n  // 把完整的所有配方子属性一并打包进模板，发布后全员可用\n  flat.materialPrices = JSON.parse(JSON.stringify(materialPrices));\n  localStorage.setItem('bh_quote_template', JSON.stringify(flat));\n  // 同时保存 materialPrices（所有配方的自定义价格）\n  localStorage.setItem('bh_material_prices', JSON.stringify(materialPrices));\n  // 同步更新内存 defaults，保证 captureDefaults 已用最新版本\n  Object.assign(defaults, flat);\n  document.getElementById('tplConfirm').style.display='none';\n  showToast('✓ 已存为模板（本地已保存，正在发布共享模板…）');\n  // 发布共享模板到仓库（所有人刷新即同步）\n  publishSharedTemplate(flat);\n}\nfunction hideTplConfirm(){ document.getElementById('tplConfirm').style.display='none'; }\n</script>\n\n<!-- Tesseract.js OCR（图片识别） -->\n<script src=\"https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js\"></script>\n<script>\n// 图片 OCR 识别 → 自动填入 parseInput → parseAndFill\nasync function ocrAndFill(inputEl){\n  const file = inputEl.files[0];\n  if(!file) return;\n  inputEl.value = ''; // 允许重复选同一张图\n  const parseResult = document.getElementById('parseResult');\n  parseResult.innerHTML = '📷 正在识别图片，请稍候…';\n  try{\n    const result = await Tesseract.recognize(file, 'chi_sim+eng', {\n      logger: m => {\n        if(m.status === 'recognizing text') parseResult.innerHTML = '📷 识别中… '+Math.round(m.progress*100)+'%';\n      }\n    });\n    const text = result.data.text.replace(/\\n+/g,' ').trim();\n    if(!text){ parseResult.innerHTML = '📷 未识别到文字，请手动输入'; return; }\n    document.getElementById('parseInput').value = text;\n    parseResult.textContent = '📷 识别结果：'+text;\n    parseAndFill();\n  }catch(e){\n    parseResult.textContent = '📷 识别失败：'+e.message;\n  }\n}\n</script>\n\n<!-- ==================== 打印报价单弹窗 ==================== -->\n<div class=\"print-overlay\" id=\"printSheetModal\" onclick=\"if(event.target===this)closePrintSheet()\">\n  <div class=\"print-sheet\">\n    <h1>报价单</h1>\n    <div class=\"ps-sub\" style=\"display:none\"></div>\n    <div class=\"ps-meta\">\n      <span>日期：<span id=\"ps_date\"></span></span>\n    </div>\n      <div class=\"ps-printopts\" id=\"ps_printopts\">\n        <span class=\"ps-opt-label\">打印内容：</span>\n        <button class=\"ps-opt\" data-opt=\"verify\" onclick=\"selectPrintOpt('verify')\">计算联</button>\n        <button class=\"ps-opt\" data-opt=\"customer\" onclick=\"selectPrintOpt('customer')\">客户联</button>\n      </div>\n    <div id=\"printSheetContent\"></div>\n    <div class=\"ps-actions\">\n      <button onclick=\"doPrintSheet()\">🖨 打印 / 另存为PDF</button>\n      <button onclick=\"exportCurrentExcel()\">📊 导出 Excel</button>\n      <button class=\"ghost\" onclick=\"closePrintSheet()\">关闭</button>\n    </div>\n  </div>\n</div>\n\n</body>\n</html>\n";
const templateKey = 'shared-template.json';
const maxRequestBytes = 512 * 1024;

function jsonResponse(value, status = 200) {
  return Response.json(value, {
    status,
    headers: { 'Cache-Control': 'no-store' }
  });
}

async function handleAdminRequest(request, env) {
  const origin = request.headers.get('Origin');
  if (origin && origin !== new URL(request.url).origin) {
    return jsonResponse({ message: '请求来源无效' }, 403);
  }
  if (!request.headers.get('Content-Type')?.startsWith('application/json')) {
    return jsonResponse({ message: '请提交 JSON 数据' }, 415);
  }
  const body = await request.text();
  if (new TextEncoder().encode(body).byteLength > maxRequestBytes) {
    return jsonResponse({ message: '模板数据过大' }, 413);
  }
  let payload;
  try {
    payload = JSON.parse(body);
  } catch {
    return jsonResponse({ message: 'JSON 格式无效' }, 400);
  }
  if (!env.ADMIN_PASSWORD) {
    return jsonResponse({ message: '云端模板服务尚未配置完成' }, 503);
  }
  if (!payload || payload.password !== env.ADMIN_PASSWORD) {
    return jsonResponse({ message: '管理员密码校验未通过' }, 403);
  }
  if (new URL(request.url).pathname === '/api/login') {
    return jsonResponse({ role: 'admin' });
  }
  if (!env.BUCKET) {
    return jsonResponse({ message: '云端模板存储尚未配置完成' }, 503);
  }
  const template = payload.template;
  if (!template || typeof template !== 'object' || Array.isArray(template)
      || !Number.isInteger(template._v)
      || typeof template._publishedAt !== 'string'
      || Number.isNaN(Date.parse(template._publishedAt))) {
    return jsonResponse({ message: '模板格式无效' }, 400);
  }
  await env.BUCKET.put(templateKey, JSON.stringify(template), {
    httpMetadata: { contentType: 'application/json; charset=utf-8' }
  });
  return jsonResponse({ ok: true, publishedAt: template._publishedAt });
}

export default {
  async fetch(request, env) {
    const { pathname } = new URL(request.url);
    try {
      if ((pathname === '/' || pathname === '/index.html')
          && (request.method === 'GET' || request.method === 'HEAD')) {
        return new Response(request.method === 'HEAD' ? null : calculatorHtml, {
          headers: {
            'Content-Type': 'text/html; charset=utf-8',
            'Cache-Control': 'no-store',
            'X-Content-Type-Options': 'nosniff'
          }
        });
      }
      if (pathname === '/shared-template.json' && request.method === 'GET') {
        if (!env.BUCKET) {
          return jsonResponse({ message: '云端模板存储尚未配置完成' }, 503);
        }
        const stored = await env.BUCKET.get(templateKey);
        return stored
          ? new Response(await stored.text(), {
            headers: {
              'Content-Type': 'application/json; charset=utf-8',
              'Cache-Control': 'no-store'
            }
          })
          : jsonResponse({ _empty: true });
      }
      if (pathname === '/api/template' || pathname === '/api/login') {
        return request.method === 'POST'
          ? await handleAdminRequest(request, env)
          : jsonResponse({ message: '请求方法无效' }, 405);
      }
      return new Response('Not found', { status: 404 });
    } catch {
      return jsonResponse({ message: '云端模板服务暂时不可用，请重试' }, 503);
    }
  }
};
